(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["5-2"] = [{"a": [54], "v": 4, "p": 379, "ev": 4, "ep": 381, "sid": 1871, "t": "وقوله عز وجل: (يا أيها الذين آمنوا من يرتد منكم عن دينه فسوف يأتي الله بقوم يحبهم ويحبونه أذلة على المؤمنين أعزة على الكافرين يجاهدون في سبيل الله ولا يخافون لومة لائم ذلك فضل الله يؤتيه من يشاء والله واسع عليم (54)\nقرأ أهل المدينة من يرتدد وذلك لغة.\nقوله ﴿أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ﴾⟪5:54⟫ أي ليني الجانب على المؤمنين،\n⟦4:380⟧\nكما قال: ﴿وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ﴾⟪17:24⟫ الآية،\nوقيل: هى فيمن ارتد في زمن أبي بكر - رضي الله عنه -، وقيل: فيمن كانوا مع النبي - صلى الله عليه وسلم -، والأظهر أنه فيهم وفي غيرهم، وأنه وعد تعالى أنه يحفظ دينهم بقوم رضي الله عنهم ورضوا عنه، ويتحرى مرضاتهم ويتحروا مرضاته، وذلك كقوله: (يا أيها الذين آمنوا ما لكم إذا قيل لكم انفروا في سبيل الله اثاقلتم إلى الأرض أرضيتم بالحياة الدنيا من الآخرة فما متاع الحياة الدنيا في الآخرة إلا قليل (38) إلا تنفروا يعذبكم عذابا أليما ويستبدل قوما غيركم ولا تضروه شيئا والله على كل شيء قدير (39).\n⟦4:381⟧\n(وإن تتولوا يستبدل قوما غيركم ثم لا يكونوا أمثالكم (38).\nوقد تقدم حقيقة محبة الله للعباد ومحبتهم له، وجعل من حقيقة محبتهم لله أن وصفهم أنهم أذلة على المؤمنين، أي متواضعين، فالتواضع الانقياد لما يورث رقة والتعزز على من يورث صعبة، وفي وصفهم بذلك وصف ينفي الجهل\nعنهم، وحصول العلم لهم، وتهذيب أنفسهم فإن التواضع ثمرة العلم وتهذيب النفس، وقد تقدم أن الجهاد ضربان: مجاهدة الغير، وذلك إما\nباللسان، وإما بالبنان، ومجاهدة النفس، وذلك بإصلاح القوة العلمية، وإصلاح القوة العملية.\nالمجاهد إما مجاهد للنفس، وإما لشياطين الإنس والجن،\nقال بعضهم: - جهاد النفس أن لا نتركها تفتر عن الطاعة، وجهاد\nالشيطان أن لا يجد منك فرصة فيأخذ منك حظا، وجهاد العدوان تدنوا من\nصفة المسلمين.\nقوله: ﴿ذَٰلِكَ فَضۡلُ ٱللَّهِ﴾⟪5:54⟫ أي الجهاد في سبيل الله، وما ذكر\nبه القدم للذين يحبهم ويحبونه: (يؤتيه) أي المستحقين."}, {"a": [55, 56], "v": 4, "p": 382, "ev": 4, "ep": 383, "sid": 1874, "t": "قوله عز وجل: (إنما وليكم الله ورسوله والذين آمنوا الذين يقيمون الصلاة ويؤتون الزكاة وهم راكعون (55) ومن يتول الله ورسوله والذين آمنوا فإن حزب الله هم الغالبون (56)\nالولي والمولى: متقاربان، لكن الولي من الأسماء المتضايفة، ويقتضي أن من واليته مواليك، وقال: ﴿ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ﴾⟪2:257⟫.\nوقال في صرضع: ﴿ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوۡلَى ٱلَّذِينَ ءَامَنُواْ وَأَنَّ ٱلۡكَٰفِرِينَ لَا مَوۡلَىٰ لَهُمۡ﴾⟪47:11⟫، وقال: ﴿يَوۡمَ لَا يُغۡنِي مَوۡلًى عَن مَّوۡلٗى شَيۡـٔٗا﴾⟪44:41⟫\nوقال: ﴿مَأۡوَىٰكُمُ ٱلنَّارُۖ هِيَ مَوۡلَىٰكُمۡۖ﴾⟪57:15⟫.\nلما نهى عن موالاة الكافرين خاطب المؤمنين بأن لا يغتروا بهم، وأن يعلموا أنهم مواليهم الله ورسوله والمؤمنون، ثم وصف المؤمنين الذين يوالونهم، فقال: ﴿يُقِيمُونَ ٱلصَّلَوٰةَ﴾⟪5:55⟫ أي يوفون حقها، لا الذين وصفهم بقوله: ﴿وَإِذَا قَامُوٓاْ إِلَى ٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ﴾⟪4:142⟫ الآية.\n﴿وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ﴾⟪5:56⟫ تقديره: من يتول\n⟦4:383⟧\nهؤلاء فهو من حزب الله، وحزب الله غالب، فإن من يتول الله ورسوله\nغالب.\n(وهم راكعون) قيل: أي خاشعون كقوله: (وما آتيتم من زكاة تريدون وجه الله فأولئك هم المضعفون (39).\nوقيل: عنى ركوع الصلاة، وذلك نزل في علي - رضي الله عنه -، فإنه تصدق بخاتم وهو في الصلاة، فالراكع يريد به الركوع\nالذي هو أحد أركان الصلاة.\nواستدل بالخبر والآية على أن الفعل القليل في الصلاة لا يبطلها،\nوفيه دلالة على أن الصدقة النافلة تسمى زكاة."}, {"a": [57, 58], "v": 4, "p": 383, "ev": 4, "ep": 385, "sid": 1875, "t": "قوله عز وجل: (يا أيها الذين آمنوا لا تتخذوا الذين اتخذوا دينكم هزوا ولعبا من الذين أوتوا الكتاب من قبلكم والكفار أولياء واتقوا الله إن كنتم مؤمنين (57) وإذا ناديتم إلى الصلاة اتخذوها هزوا ولعبا ذلك بأنهم قوم لا يعقلون (58)\n⟦4:384⟧\nالذين آمنوا هم المخاطبون في قوله: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ﴾⟪5:54⟫، والمذكورون في قوله: ﴿وَٱلَّذِينَ ءَامَنُواْ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ﴾⟪5:55⟫\nونهاهم عن موالاة المتهكمين بدين الحق أي عن الاستعانة بالمشركين،\nوقد روي أن قوما من اليهود أتوه ليخرجوا معه، فقال عليه الصلاة والسلام: (إنا لا نستعين بمشرك)، وقد تقدم أن الاستعانة بهم لا تجوز على وجه يكونون هم الغالبون.\nفأما أن يستخدموا في المهن، وما يورثهم المهانة لا العز فجائز.\nقرئ (والكفار) بالنصب، معطوفا على قوله: ﴿ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا﴾⟪5:57⟫،\n⟦4:385⟧\nوبالجر معطوفا على قوله: ﴿مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ﴾⟪5:57⟫ وعنى بالكفار من عدا أهل الكتاب من ملحد وعابد وثن،\nوقوله: ﴿وَٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ﴾⟪5:57⟫ تنبيه: أن من شرط الإيمان مضامة التقوى، ومن شرط التقوى الغضب لدين الله، وترك موالاة من اتخذ دينكم هزوا ولعبا، ومن لا يغضب لدينه فليس بمؤمن حقيقة.\nوقوله: ﴿وَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ﴾⟪5:58⟫ معطوف على قوله:\n﴿ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا﴾⟪5:57⟫ وداخل في صلة الدين، ومن تمام\nوصفهم كأنه قيل: اتخذوا دينكم هزوا ولعبا واتخذوا الصلاة هزوا ولعبا إذا ناديتم إلى الصلاة، وهذا تخصيص بعد العموم، أي يتخذون الدين جملة هزوا\nولعبا، ويتخذون النداء إلى الصلاة كذلك، ونحوه قوله: ﴿وَإِذَا عَلِمَ مِنۡ ءَايَٰتِنَا شَيۡـًٔا ٱتَّخَذَهَا هُزُوًاۚ﴾⟪45:9⟫ و (من) في قوله: ﴿مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ﴾⟪5:57⟫ للتبيين وإظهار ذلك من يفعل ذلك وليس هو التخصيص."}, {"a": [59], "v": 5, "p": 386, "ev": 5, "ep": 387, "sid": 1878, "t": "قوله عز وجل: (قل يا أهل الكتاب هل تنقمون منا إلا أن آمنا بالله وما أنزل إلينا وما أنزل من قبل وأن أكثركم فاسقون (59)\nيقال: نقم ونقم عليه نقمة إذا أنكر ما فعله وسخط عليه ولتضمين النقمة\nالسخط والإنكار استعمل في كل واحد منهما على الانفراد، والسبب في نزول هذه الآية أن قوما من اليهود أتوا النبي - صلى الله عليه وسلم - فسألوه: عن من يؤمن بالله، فقال: ﴿ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ﴾⟪2:136⟫\nالآية، فلما سمعوا ذكر عيسى نقموا فأنزل الله ذلك تنبيها أنكم أنكرتم غير\nمنكر وهو إيماننا مع فسقكم، ومخرج هذا الكلام الإنكار لقول الشاعر:\n⟦5:387⟧\nوما نقموا من بني امية إلا ... أنهم يحلمون إن غضبوا"}, {"a": [60], "v": 5, "p": 387, "ev": 5, "ep": 389, "sid": 1879, "t": "قوله تعالى: (قل هل أنبئكم بشر من ذلك مثوبة عند الله من لعنه الله وغضب عليه وجعل منهم القردة والخنازير وعبد الطاغوت أولئك شر مكانا وأضل عن سواء السبيل (60)\nالمثوبة في الخير كالعقوبة من الشر، واستعارتها للعقوبة نحو قول الشاعر: -\n... تحية بينهم ضرب وجيع\nوقول غيره:\nتعليقها الإسراج والإحكام.\nذكر أن إيماننا بالله وما أنزل إلينا إن كان شرا عندكم، فإني أنبئكم بما هو شر عاقبة عند الله منه وهو ممن أبعدهم الله من رحمته وسخط عليهم ومسخهم القردة والخنازير\nوقوله: ﴿شَرّٞ مَّكَانٗا﴾⟪5:60⟫ أي متصرفا، وأضل عن الطريق المستقيم.\nوقوله: ﴿وَعَبَدَ ٱلطَّٰغُوتَۚ﴾⟪5:60⟫ معطوف على قوله: ﴿لَّعَنَهُ ٱللَّهُ﴾⟪5:60⟫ أي من لعنه الله\n⟦5:388⟧\nومن عبد الطاغوت أي الشيطان وعبادته الشيطان طاعته إياه فيما سول له.\nوقرأ ابن مسعود (وعبدوا) ردا إلى المعنى وهو أجود.\nوقرئ وعبد الطاغوت وعبد الطاغوت.\nفمن قرأ عبد فليس بوجه عند أهل العربية، لأنه ليس من\n⟦5:389⟧\nأمثله الجمع، وقد فسرنا به خدم الطاغوت، وأما عبد فجمع عبيد، نحو رغيف ورغف، وسرير وسرر، وتقدير ذلك وجعل منهم عبد\nالطاغوت، كقولك جعلت زيدا أخاك أي حكمت بذلك وأما عبد فإما أنه\nواحد وقع موقع الجمع، أو جعل جمع عابد نحو خدم، أو أصله عبد فسكن نحو عضد وعضد."}, {"a": [61], "v": 5, "p": 389, "ev": 5, "ep": 389, "sid": 1881, "t": "قوله عز وجل: (وإذا جاءوكم قالوا آمنا وقد دخلوا بالكفر وهم قد خرجوا به والله أعلم بما كانوا يكتمون (61)\nأي يظهرون الإيمان ويدخلون كافرين، ويخرجون كافرين، تنبيها أنهم كاذبون فيما يظرون من الإيمان و (وإذا) إشارة إلى قوله: ﴿وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ إِلَىٰ شَيَٰطِينِهِمۡ قَالُوٓاْ إِنَّا مَعَكُمۡ إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ﴾⟪2:14⟫.\nوإلى نحو قوله: ﴿مِنَ ٱلَّذِينَ قَالُوٓاْ ءَامَنَّا بِأَفۡوَٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ﴾⟪5:41⟫."}, {"a": [62, 63], "v": 5, "p": 389, "ev": 5, "ep": 392, "sid": 1881, "t": "قوله عز وجل: (وترى كثيرا منهم يسارعون في الإثم والعدوان وأكلهم السحت لبئس ما كانوا يعملون (62)\n⟦5:390⟧\nفي ذلك مسابقتهم إليه، وذلك في السوء\nكقوله في الحسنى: ﴿يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَهُمۡ لَهَا سَٰبِقُونَ﴾⟪23:61⟫\nوحث لها، وقال: ﴿سَابِقُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ﴾⟪57:21⟫.\nوالإثم إشارة إلى نحو الذي قال: ﴿وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ﴾⟪5:45⟫.\nوأكلهم السحت إلى قوله: ﴿فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ﴾.\nالإثم أعم من العدوان، والعدوان أخص منه وأعم من\nأكل السحت، وأكل السحت أخص منهما لأن كل أكل\nالسحت عدوان، وليس كل عدوان يكون أكلا للسحت.\nقوله عز وجل: لولا ينهاهم الربانيون والأحبار عن قولهم الإثم وأكلهم السحت لبئس ما كانوا يصنعون (63)\n⟦5:391⟧\nلولا إذا دخل على فعل ماضي فالتوبيخ: (لولا جاءوا).\nوإذا دخل على فعل مستقبل فللتخصيص.\nوالرباني منسوب إلى الرب وهو الذي تولى الله تربيته بالعلم،\nقرأ عبادة: بزيادة الألف والنون فيه كقولهم: شعراني.\nوقال بعضهم: الرباني ليس في كلامهم في الأصل.\nوالأحبار الذين يراعون الأعمال، وأصله من حبرت أي حسنت\nوكان عبارة عن المحسنين.\n⟦5:392⟧\nإن قيل: (يعملون) وفي الثانية: (يصنعون) وهل بينهما فرق؟\nقيل: الصنع أخص من العمل كما أن العمل أخص من الفعل، وذاك أن الفعل يقال فيما كان من الحيوان، وغير الحيوان وبقصد وعن غير قصد، والعمل لا يقال إلا ما كان من الحيوان وبقصد، والصنع لا يقال إلا ما كان من الإنسان بقصد واختيار وبعد فكر وتحري أحاده، ولهذا يقال: دخل رجل صانع أي حاذق، وثوب صنيع أي مجاد. فحيثما ذكر كافتهم قال:\n﴿لَبِئۡسَ مَا كَانُواْ يَعۡمَلُونَ﴾⟪5:62⟫ وحيثما ذكر خاصتهم وحفظة العلم والعمل ذكر: ﴿لَبِئۡسَ مَا كَانُواْ يَصۡنَعُونَ﴾⟪5:63⟫."}, {"a": [64], "v": 5, "p": 392, "ev": 5, "ep": 396, "sid": 1884, "t": "قوله عز وجل: (وقالت اليهود يد الله مغلولة غلت أيديهم ولعنوا بما قالوا بل يداه مبسوطتان ينفق كيف يشاء وليزيدن كثيرا منهم ما أنزل إليك من ربك طغيانا وكفرا وألقينا بينهم العداوة والبغضاء إلى يوم القيامة كلما أوقدوا نارا للحرب أطفأها الله ويسعون في الأرض فسادا والله لا يحب المفسدين (64)\nقوله: ﴿يَدُ ٱللَّهِ مَغۡلُولَةٌۚ﴾⟪5:64⟫ أي هو بخيل ممسمك، كقوله: ﴿وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ﴾⟪17:29⟫\n⟦5:393⟧\nوقيل قالوا: إنه فقير كقوله: ﴿لَّقَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ فَقِيرٞ وَنَحۡنُ أَغۡنِيَآءُۘ﴾⟪3:181⟫، قال الحسن: معناه: - يده مقبوضة عن\nعذابنا، وقوله: ﴿غُلَّتۡ أَيۡدِيهِمۡ﴾⟪5:64⟫ دعاء عليهم،\nوقيل: هو خبر، والدعاء والخبر إذا كانا من الله واحد،\nوقول من قال: لو كان هذا إخبارا لوجدوا لذلك، فلعمري إنهم قد وجدوا كذلك، فقد روي أن اليهود أبخل خلق الله،\nوقوله: ﴿بَلۡ يَدَاهُ مَبۡسُوطَتَانِ﴾⟪5:64⟫ نعمه متكاثرة،\nوتشبيه اليد على طريقة كلام العرب في استعارة هذه اللفظة.\nوقد ذكر لفظ اليد في آيات.\nوقيل: تتنيتها لأنه أراد عطية الدنيا والآخرة، وقيل: بل قصدا إلى ثوابه\nوعقابه، وقيل: بل قصد إلى تكثير نعمه.\nفالتثنية يعبر بها عن كل كثرة\n⟦5:394⟧\nنحو قولهم: لبيك وسعديك.\nوقوله: ﴿يُنفِقُ كَيۡفَ يَشَآءُۚ﴾⟪5:64⟫ أي إنفاقه على مقتضى الحكمة لا على حسب شهوتكم.\nوقوله: ﴿وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۚ﴾⟪5:64⟫\nما يسمعون من\n⟦5:395⟧\nالقرآن، ووجه ذلك ما تقدم أن القرآن بمنزلة الغذاء، والمعقولات بمنزلة\nالدواء الذي يوازي الصحة، والكافر والمنافق مريضان، كما قال: ﴿فِي قُلُوبِهِم مَّرَضٞ﴾. فكما أن المريض لا يوافقه الغذاء بل يزيده مرضا كذلك\nالمنافق يزداد بسماع القرآن طغيانا وكفرا.\nوإلقاء العدواة بينهم هو تعريف لليهود قبح اتخاذ النصارى المسيح ربا، وتعريف النصارى قبح نسبة اليهود المسيح إلى أما هو أقبح به.\nويدخل في ذلك معاداة النصارى بعضهم لبعض،\nوقوله: ﴿كُلَّمَآ أَوۡقَدُواْ نَارٗا لِّلۡحَرۡبِ﴾⟪5:64⟫ أي إذا هموا بإثارة شر\nأوقع الله بينهم منازعة تكف شرهم وتدفع شوكتهم، فمنازعتهم لبعض يورث فشلا، كما قال: ﴿وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ﴾⟪8:46⟫.\nوقال في الكفار:\n⟦5:396⟧\n﴿تَحۡسَبُهُمۡ جَمِيعٗا وَقُلُوبُهُمۡ شَتَّىٰۚ﴾⟪59:14⟫ وقال: ﴿بَأۡسُهُم بَيۡنَهُمۡ شَدِيدٞۚ﴾⟪59:14⟫،\nوقوله: ﴿وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادٗاۚ﴾⟪5:64⟫ أي مساعاتهم\nلطلب الإفساد فلا يعينهم الله، فإن الله لا يحب المفسدين، أي لا يعينهم\nعلى تحريهم الفساد."}, {"a": [65], "v": 5, "p": 396, "ev": 5, "ep": 396, "sid": 1888, "t": "قوله عز وجل: (ولو أن أهل الكتاب آمنوا واتقوا لكفرنا عنهم سيئاتهم ولأدخلناهم جنات النعيم (65)\nالتكفير: ستر الذنوب حتى تصير بمنزلة ما لم يعمل، ويصح أن يكون أصله\nإزالة الكفر كقولهم: مرضت فلان وقديت عينه.\nذكر أنهم لو أصلحوا اعتقادهم وأفعالهم لغفروا وأثيبوا، كقوله: ﴿قُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ يُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ﴾⟪8:38⟫."}, {"a": [66], "v": 5, "p": 396, "ev": 5, "ep": 398, "sid": 1888, "t": "قوله عز وجل: (ولو أنهم أقاموا التوراة والإنجيل وما أنزل إليهم من ربهم لأكلوا من فوقهم ومن تحت أرجلهم منهم أمة مقتصدة وكثير منهم ساء ما يعملون (66)\n⟦5:397⟧\nكما جعل تعالى لجزاء إيمانهم تكفير السيئات، وجزاء تقواهم\nإدخال الجنات، جعل جزاء توفية أحكام كتب الله سعة الرزق، وذلك أنهم\nلما اشتروا بآيات الله ثمنا قليلا، وكتموا ما أنزل الله بسحت كانوا يحوزونه، بين تعالى أن ذلك العرض بل أكثر منه وأطيب لم يكن ليفوتهم لو وفوا كتب الله حقها.\nوالأكل من فوقهم إشارة إلى الثمار ومن تحت أرجلهم إلى الزروع.\nوقيل: بل الإشارة بقوله: ﴿مِن فَوۡقِهِمۡ﴾⟪5:66⟫ إلى المطر، وبقوله: ﴿وَمِن تَحۡتِ أَرۡجُلِهِمۚ﴾⟪5:66⟫ إلى الثمار والحبوب جميعا، كقوله: (ونزلنا من السماء ماء مباركا فأنبتنا به جنات وحب الحصيد (9) والنخل باسقات لها طلع نضيد (10).\nوقيل: ذلك إشارة إلى أنهم كانوا ينالونها، قال: ﴿فَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ رَغَدٗا﴾⟪2:58⟫ وعلى هذا:\n⟦5:398⟧\n(استغفروا ربكم إنه كان غفارا (10) يرسل السماء عليكم مدرارا (11).\nوقوله ﴿وَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰٓ ءَامَنُواْ وَٱتَّقَوۡاْ لَفَتَحۡنَا عَلَيۡهِم بَرَكَٰتٖ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ﴾⟪7:96⟫، وقوله: ﴿وَأَلَّوِ ٱسۡتَقَٰمُواْ عَلَى ٱلطَّرِيقَةِ لَأَسۡقَيۡنَٰهُم مَّآءً غَدَقٗا﴾⟪72:16⟫،\nوقوله: (ومن يتق الله يجعل له مخرجا (2) ويرزقه من حيث لا يحتسب).\nوقوله: ﴿مِّنۡهُمۡ أُمَّةٞ مُّقۡتَصِدَةٞۖ﴾⟪5:66⟫ أي عادلة غير عادية ولا مقصره وهم الذين آمنوا بمحمد - صلى الله عليه وسلم -، وذلك كقوله: ﴿لَيۡسُواْ سَوَآءٗۗ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ﴾⟪3:113⟫.\nوقوله: ﴿سَآءَ مَا يَعۡمَلُونَ﴾⟪5:66⟫ نحو: ﴿سَآءَ مَثَلًا ٱلۡقَوۡمُ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا﴾⟪7:177⟫\nوقوله: ﴿سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا﴾⟪25:66⟫."}, {"a": [67], "v": 5, "p": 399, "ev": 5, "ep": 401, "sid": 1891, "t": "قوله تعالى: (يا أيها الرسول بلغ ما أنزل إليك من ربك وإن لم تفعل فما بلغت رسالته والله يعصمك من الناس إن الله لا يهدي القوم الكافرين (67)\nقيل: السبب في نزول هذه الآية أن النبي - صلى الله عليه وسلم - كان يهاب قريشا، فأنزل الله ذلك.\nفروي: (أن أعرابيا هم بقتل النبي - صلى الله عليه وسلم - فسقط السيف من يده فجعل يضرب برأسه حتى انتثر دماغه).\nإن قيل: كيف قال: ﴿وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ﴾⟪5:67⟫ وذلك كقوله: إن لم تبلغ فما بلغت.\nقيل معناه: وإن لم تبلغ كل ما أنزل إليك يكون في حكم من لم تبلغ شيئا، تنبيها أن تقصيرك في بعض ما أمرت به يحبط عملك.\nوقيل: عنى بقوله: ﴿مَآ أُنزِلَ إِلَيۡكَ﴾⟪5:67⟫ ما ذكره بعد هذه الآية.\nوهو قوله: ﴿قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَسۡتُمۡ عَلَىٰ شَيۡءٍ حَتَّىٰ تُقِيمُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡۗ﴾⟪5:68⟫.\nوقوله: ﴿وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ﴾⟪5:67⟫ أي يمنعك من أن ينالوك\n⟦5:400⟧\nبسوء من قتل أو أسر أو قهر. وأصل العصم: من عصم القربة أي\nشدها، وعصمة الله للعبد حفظ سره بما يرد عليه من موارد الشر.\nوقيل: معنى يعصمك من الناس أي من بينهم العصمة المختصة بالنبوة ونحو قوله: (فاصدع بما تؤمر وأعرض عن المشركين (94) إنا كفيناك المستهزئين (95).\nوقوله: ﴿إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ﴾⟪5:67⟫.\nليس يعني أنه لا يبذل لهم فعصمة الله وتوفيقه وتسديده مبذولة\nلكل من رغب فيها وترشح لقبولها.\nولكن الكفر يمنع منه، فإنه يعانده وينافيه كمنافاة المتضاد.\nواستدل بهذه الآية على أن النبي - صلى الله عليه وسلم - لا يكتم شيئا مما أنزل الله بخلاف ما قالت الرافضة: أنه قد كتم أشياء على سبيل التقية.\n⟦5:401⟧\nقال بعض الصوفية: ما يتعلق به مصالح العباد وأمر بإطلاعهم عليه، فمنزه عن\nكتمانه، وأما ما خص به من الغيب ولم يتعلق به مصالح أمته فله بل عليه\nكتمانه."}, {"a": [68], "v": 5, "p": 402, "ev": 5, "ep": 403, "sid": 1894, "t": "قوله عز وجل: (قل يا أهل الكتاب لستم على شيء حتى تقيموا التوراة والإنجيل وما أنزل إليكم من ربكم وليزيدن كثيرا منهم ما أنزل إليك من ربك طغيانا وكفرا فلا تأس على القوم الكافرين (68)\n⟦5:403⟧\nإن قيل: قوله: ﴿وَمَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡۗ﴾⟪5:68⟫ داخل فيه التوراة والإنجيل إذ كل ذلك منزل من الله، فلم أفردا؟\nقيل: إنه أفردهما بالذكر على سبيل التفصيل وخص ما أنزل بالقرآن.\nفإن قيل كيف أمرهم أن يقيموا الكتب وقد علم أن القرآن قد نسخ\nالتوراة والإنجيل، ولا يصح إقامة جميعها؟\nقيل: يجوز أنه عنى الإقرار بصحة ثلاثتها، ويجوز أنه أراد أحكام أصولها، فإن ثلاثتها تستوي في ذلك وإنما الاختلاف في الفروع\nبسحب مصالح الأزمنة.\nوقيل: أراد إقامة هذه الكتب بإظهار ما فيه\nمن وصف النبي - صلى الله عليه وسلم - وتصديق بعضها بعضا."}, {"a": [69], "v": 5, "p": 403, "ev": 5, "ep": 406, "sid": 1895, "t": "قوله عز وجل: (إن الذين آمنوا والذين هادوا والصابئون والنصارى من آمن بالله واليوم الآخر وعمل صالحا فلا خوف عليهم ولا هم يحزنون (69)\n⟦5:404⟧\nإن قيل: كيف قال: ﴿مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ﴾⟪2:126⟫ و (من) يدل على ما تقدم، وتقديره: من آمن من المؤمنين ومن الذين هادوا، وذلك خلف من\nالكلام؟\nقيل في ذلك وجهان:\nأحدهما: أن معنى قوله: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ﴾⟪5:69⟫: أظهروا الإيمان وأمنوا من القتل والسبي وهم الموصوفون بقوله: ﴿مِنَ ٱلَّذِينَ قَالُوٓاْ ءَامَنَّا بِأَفۡوَٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ﴾⟪5:41⟫.\nوقوله: ﴿مَنۡ ءَامَنَ مِنۡهُم﴾ أي من يحقق الإيمان فبين أن المظهر للإيمان، والذين ما داموا فيهم ممن ذكرهم، لا يسقط عنهم الخوف والحزن في الدارين ما لم يتحققوا بتصديق الله، والإيمان بالمعاد، والتحري لمصالح الأعمال والثاني من في قوله: ﴿مَنۡ ءَامَنَ بِٱللَّهِ﴾⟪5:69⟫ راجع إلى قوله: ﴿وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـُٔونَ﴾⟪5:69⟫ دون قوله: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ﴾⟪5:69⟫.\nإن قيل : ما وجه قوله: (والصابئون) وقد ذكر النحويون أن المعطوف على اسم (إن) قبل الخبر لا يصح فيه الرفع؟\nقيل إن ذلك لا يصح منه الرفع إذا عطف على موضع إن\n⟦5:405⟧\nويخبر عنهما بخبر واحد نحو أن يقول: إن زيدا وعمرو منطلقان، فأما إذا جعل الثاني مرتفعا بالابتداء وجعل خبر أحدهما مضمرا يصح.\nكقول الشاعر:\n..........\nفإنى وقيار بها لغريب\nوتقدير الكلام: إن الذين آمنوا لا خوف عليهم، والذين هادوا والصابئون\nوالنصارى من آمن بالله لا خوف عليهم، واستغنى بخبر أحدهما عن مضمر\nالآخر وعلى هذا قول الشاعر:\nوإلا فاعلموا أنا وأنتم ... بغاة ما بقينا في شقاق\nوقيل: قوله: ﴿وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـُٔونَ﴾⟪5:69⟫ معطوف\n⟦5:406⟧\nعلى المضمر في قوله: (ءامنو) كأنه قيل: إن الذين آمنوا هم\nوالذين هادوا والصابئون.\nقال الفراء: الرفع يصح بعد إن ويصح في كل معطوف، ولا يتغير فيه الإعراب نحو الذي وإخوانه، وهذا وهذه."}, {"a": [70], "v": 5, "p": 406, "ev": 5, "ep": 407, "sid": 1898, "t": "قوله عز وجل: (لقد أخذنا ميثاق بني إسرائيل وأرسلنا إليهم رسلا كلما جاءهم رسول بما لا تهوى أنفسهم فريقا كذبوا وفريقا يقتلون (70)\nقد تقدم حقيقة أخذ الميثاق منهم، وأن ذلك بما ضمن عقولهم على ما دل عليه قوله:\n⟦5:407⟧\n﴿وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ﴾⟪7:172⟫ الآية.\nوبعضه بما أنزل إليهم من الآيات، وبعضه بالأيمان المؤكدة وكل ذلك مما ذكره المفسرون، وإنما قال: ﴿فَرِيقٗا كَذَّبُواْ وَفَرِيقٗا يَقۡتُلُونَ﴾⟪5:70⟫ فعطف\nالمستقبل على الماضي تنبيها على أن ذلك عادتهم ماضيا ومستقبلا،\nونبه بقوله: ﴿بِمَا لَا تَهۡوَىٰٓ أَنفُسُهُمۡ﴾⟪5:70⟫ أنهم يتبعون الهوى فيما يتحرونه، فلا\nيستحقون جهدا وإن طابقو الحق إذ ليس لهم إلا سلوك سبيل الهوى، وأصل\nالهوى: والهوا واحد وهو لا مساك له، ومنه: ﴿ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ﴾⟪6:71⟫، وسمى الدار هاوية لذلك."}, {"a": [71], "v": 5, "p": 407, "ev": 5, "ep": 408, "sid": 1899, "t": "قوله عز وجل: (وحسبوا ألا تكون فتنة فعموا وصموا ثم تاب الله عليهم ثم عموا وصموا كثير منهم والله بصير بما يعملون (71)\nالفتنة العذاب والبلية، وأصلها: إدخال الذهب والفضة النار\n⟦5:408⟧\nللاختيار، ولذلك قال تعالى: ﴿يَوۡمَ هُمۡ عَلَى ٱلنَّارِ يُفۡتَنُونَ﴾⟪51:13⟫، وتارة يعتبر ما تحمل من العذاب فيستعمل فيه نحو: ﴿وَفَتَنَّٰكَ فُتُونٗاۚ﴾⟪20:40⟫.\nوقرأ: (ألا تكون) بالرفع والنصب. فالرفع على\nتقدير أنه لا تكون فتنة وذلك أبلغ في ذمهم، وقد تقدم أن الظن والحسبان\nيستعملان تارة فيما قوى في النفس وتارة لما ضعف، ومن ذكر بعدهما إن\nالمشددة والمخففة منهما فقصد إلى تقوية الاعتقاد ومن ذكر بعدهما أن الناصبة\nللفعل فلضعف الاعتقاد، وارتفاع قوله: (كثير) على البدل من الضمير في\n: (فعموا وصموا) وعلى تقدير التفسير: أي العمي والصم كثير منهم ثم\nبين أنه تعالى لعلمه كاملا بما يعملون بالمرصاد يحاربهم."}, {"a": [72], "v": 5, "p": 408, "ev": 5, "ep": 409, "sid": 1900, "t": "قوله تعالى: (لقد كفر الذين قالوا إن الله هو المسيح ابن مريم وقال المسيح يا بني إسرائيل اعبدوا الله ربي وربكم إنه من يشرك بالله فقد حرم الله عليه الجنة ومأواه النار وما للظالمين من أنصار (72)\n⟦5:409⟧\nقالوا: إن الله هو المسيح، وذلك حكاية عن اليعقوبية\nالذين قالوا إن المسيح ابن مريم هو الله، وبين أن المسيح نهاهم أن\nيعتقدوا ذلك حيث قال: اعبدوا الله ربي وربكم وأنه بين أن من يشرك\nبالله يمنعه الجنة ويخلده النار فلا يجد ناصرا.\nوأصل التحريم جعل الشيء ممنوعا منه إما بالحكم كتحريم الله الخمر وإما بالمنع القهري كتحريم الله الجنة على الكافر."}, {"a": [73, 74], "v": 5, "p": 409, "ev": 5, "ep": 410, "sid": 1901, "t": "قوله تعالى: (لقد كفر الذين قالوا إن الله ثالث ثلاثة وما من إله إلا إله واحد وإن لم ينتهوا عما يقولون ليمسن الذين كفروا منهم عذاب أليم (73) أفلا يتوبون إلى الله ويستغفرونه والله غفور رحيم (74)\nأخبر عن النسطورية والملكية، فهم الذين يقولون أب وابن وروح القدس فيجعلون الله أحد الأقانيم الثلاثة، ومن أن الله هو واحد وهو سبب الموجودات، وهددهم إن لم ينتهوا يعذبون.\n⟦5:410⟧\nإن قيل: لم قال: ﴿لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٌ﴾⟪5:73⟫،\nوذلك يقتضي أن يكون بعض منهم كافرين.\nوقد قال: ﴿لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ﴾⟪5:73⟫ فحكم بكفر جميعهم قيل: إنما قال الذين كفروا منهم تنبيها أن العذاب يتوجه على من دام به الكفر ولم يقلع، ولهذا عقبه بقوله: ﴿أَفَلَا يَتُوبُونَ﴾⟪5:74⟫.\nإن قيل: لم قال: (ليمسن) فذكر المس، وذلك يقتضي بتقليل العذاب.\nقيل: بل المس يقتضي مبالغة في وصف عذابهم، لأن المس يقتضي اللمس، وذلك أعم الحواس وأكثرها وجودا إذ لا حيوان إلا وله اللمس، ولأنه أعرف الحواس عند الخاص والعام."}, {"a": [75], "v": 5, "p": 410, "ev": 5, "ep": 412, "sid": 1902, "t": "قوله عز وجل: (ما المسيح ابن مريم إلا رسول قد خلت من قبله الرسل وأمه صديقة كانا يأكلان الطعام انظر كيف نبين لهم الآيات ثم انظر أنى يؤفكون (75)\nالصديقة الكثيرة الصدق، فقد قيل: إنها لم تكذب قط،\nوقيل: لتصديقها جبريل لما قال:\n⟦5:411⟧\n(إنما أنا رسول ربك لأهب لك غلاما زكيا (19).\nالخلو: تعري الزمان أو المكان مما فيه، أو تعرى الشيء من زمان ومكان. وإذا قيل: لا يخلوا الأمر من كذا، فمعناه لا يتعرى ولا ينفك،\nاحتج تعالى على من ادعى الربوبية لعيسى بما يزيل الشبهة في ذلك، وهو أن غاية ما لعيسى صلى الله عليه وسلم كونه رسولا، ذا معجزات قد شاركه في مثلها غيره من الأنبياء كإبراهيم حيث ألقي في النار فسلم منها، وموسى حيث ألقى عصاه فإذا هي ثعبان مبين، وفلق البحر له في تسع آيات، وأنه في كونه من غير أب لم يكن بأعجب من آدم الذي\nكان من غير أب ولا أم، ونبه على قصوره عن آدم بكونه من أم، وأن كونها\nصديقه لا يقتضي لها ولا لابنها الربوبية بل أكثر ما في ذلك أن يكونا من جملة\nالصديقين، ثم نبه على بعضهما بافتقارهما إلى الطعام المقتضي لبعض الحاجة فكنى تعالى عن ذلك بأحسن كناية ثم عجب منهم بقوله: ﴿ٱنظُرۡ كَيۡفَ نُبَيِّنُ لَهُمُ ٱلۡأٓيَٰتِ ثُمَّ ٱنظُرۡ أَنَّىٰ يُؤۡفَكُونَ﴾⟪5:75⟫ وإذا كان حالهما لا يخفى ومع\nذلك ينصرفون عن الحق وتفهمه.\nقيل معنى: (يؤفكون): يصرفون\n⟦5:412⟧\nكاذبون فيما يدعونه."}, {"a": [76], "v": 5, "p": 412, "ev": 5, "ep": 414, "sid": 1904, "t": "قوله تعالى: (قل أتعبدون من دون الله ما لا يملك لكم ضرا ولا نفعا والله هو السميع العليم (76)\nإن قيل لم قال: ﴿مَا لَا يَمۡلِكُ﴾⟪5:76⟫ ولم يقل (من)، وقد قصد بذلك نفي إلاهية\nعيسى، وكيف قال: ﴿يَمۡلِكُ لَهُمۡ ضَرّٗا وَلَا نَفۡعٗا﴾⟪20:89⟫ وقد كان عيسى\nيملك ذلك وإن كان بتخليق الله إياه، ولم قدم الضر على النفع، ولم أتبع ذلك قوله: ﴿وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ﴾⟪5:76⟫، وقد كان من حق المقابلة أن يقال\nوالله هو الضار النافع؟\nقيل: أما ذكر (ما) فلكونه للجنس والنوع المقتضين لمعنى عام يقصد بذكره وأن ذلك يقتضي المشاركة والمشابهة، وتنزه الإلهية عن ذلك فأنكر تعالى بذكر ما ادعوه كل ما اقتضى مشابهة ما، وإنما قال:\n﴿لَا يَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا نَفۡعٗاۚ﴾⟪5:76⟫ لأنه لما كانت الإشارة على ثلاثة\n⟦5:413⟧\nأضرب: عن مالك الضر والنفع بوجه، ومالك لبعض ذلك بتمليك كالإنسان، ومالك لهما لا تمليك وهو الله تعالى صار مالكا، لذلك بالتمليك في الحكم من لا يملك من هذا الوجه.\nقال المسلمون: لا يملك أحد شيئا غير الله، وقالوا:\nالأشياء في يد الناس عارية مستردة. وأما تقديم الضر على النفع؛ فلأن الإنسان يخدم غيره إما لدفع الضرر أو لجر النفع، والناس يراعون دفع الضرر قبل جر النفع، ولذلك كان الاحتراز من المضارة كلها واجبا وليس طلب المنافع كلها واجبا، فلذلك قدم هاهنا الضرر.\nفإن قيل: فقد قاله: ﴿قُل لَّآ أَمۡلِكُ لِنَفۡسِي نَفۡعٗا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُۚ﴾⟪7:188⟫\nفقدم ذكر النفع؟\nقيل: تقدم النفع في هذا المكان أولى لأنه لما ذكر تحريهم عن أنفسهم فيما يجرون لها.\nوالإنسان يتحرى لنفسه النفع لا الضر، بين أنهم لا يملكون ما يحبون\nفلأنفسهم، بل لا يملكون أيضا في حقيقة الضر فضلا عن النفع.\nوأما إتباعه بقوله: ﴿وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ﴾⟪5:76⟫ فهو أنه لما لم ينكروا أن الله مالك الضر والنفع، ولا أنه قادر على مجازاة من استحق المجازاة، بل أشركوا بينه وبين غيره عقبه بما اقتضى معنى ملكه للضر والنفع، وقدرته على المجازاة وذكر أنه هو المجازي\n⟦5:414⟧\nفإن قوله: ﴿ٱلسَّمِيعُ ٱلۡعَلِيمُ﴾⟪5:76⟫ اقتضى أنه يجازي بما يسمعه\nويعلمه، وإدخال هو في قوله: ﴿وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ﴾⟪5:76⟫ اقتضى أن هذا الحكم خاص له لا يشاركه فيه غيره، صار مقتضى الكلام أنه يملك النفع والضر وأنه يجازي كل أحد باستحقاقه."}, {"a": [77], "v": 5, "p": 414, "ev": 5, "ep": 416, "sid": 1906, "t": "قوله عز وجل: (قل يا أهل الكتاب لا تغلوا في دينكم غير الحق ولا تتبعوا أهواء قوم قد ضلوا من قبل وأضلوا كثيرا وضلوا عن سواء السبيل (77)\nالغلو: تجاوز الحد من قولهم غلا السهم وغلا السعر ويستعمل في الإفراط\nدون التفريط، والخطاب قيل هو للنصارى حيث تجاوز القصد في عيسى\nعليه الصلاة والسلام فادعوا له الربوبية.\nوقيل: هو خطاب لهم ولليهود، فالنصارى غلوا في رفعه،\nواليهود في وضعة،\nوقوله: ﴿غَيۡرَ ٱلۡحَقِّ﴾⟪5:77⟫ انتصب بإضمار: (ولا تقولوا) كقوله: ﴿وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ﴾⟪4:171⟫، وبين أن الذي عليه قومهم هو من مقتضى الهوى فنهاهم عن اتباعهم فيه.\n⟦5:415⟧\nكما قال تعالى: ﴿وَٱسۡتَقِمۡ كَمَآ أُمِرۡتَۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡۖ﴾⟪42:15⟫\nوإنما جمع الهوى تنبيها أنهم متفاوتون، والمراد في باطلهم،\nإن قيل: لم كرر قوله: (ضلوا)؟\nقيل في ذلك أوجه: الأول: أنه أراد قد ضلوا عن سواء السبيل،\nفلما فصل بينه وبين ما يتعلق به أعيد ذكره، كقوله: ﴿لَا تَحۡسَبَنَّ ٱلَّذِينَ يَفۡرَحُونَ بِمَآ أَتَواْ وَّيُحِبُّونَ أَن يُحۡمَدُواْ بِمَا لَمۡ يَفۡعَلُواْ فَلَا تَحۡسَبَنَّهُم بِمَفَازَةٖ مِّنَ ٱلۡعَذَابِۖ﴾⟪3:188⟫.\nأعاد قوله: ﴿فَلَا تَحۡسَبَنَّهُم﴾⟪3:188⟫.\nالثاني: أنه أريد ضلوا وأضلوا عن سواء السبيل، ضلوا كون ذلك تبينا لما ضلوا عنه،\nوالثالث: أن الاشارة بقوله: ﴿ضَلُّواْ مِن قَبۡلُ﴾⟪5:77⟫ إلى ضلالهم في شريعتهم قبل إتيان نبينا - صلى الله عليه وسلم -،\n⟦5:416⟧\nوبقوله: ﴿وَضَلُّواْ عَن سَوَآءِ ٱلسَّبِيلِ﴾⟪5:77⟫ إلى ما أتى به النبي - صلى الله عليه وسلم -.\nوالرابع: أن الإنسان قد يعتقد أن يضل غيره وهو ضال بذلك، فبين الله تعالى أن هؤلاء ضلوا في أنفسهم وضلوا بإضلالهم غيرهم إشارة إلى نحو قوله: ﴿لِيَحۡمِلُوٓاْ أَوۡزَارَهُمۡ كَامِلَةٗ يَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيۡرِ عِلۡمٍۗ﴾⟪16:25⟫.\nوالخامس: أن الله تعالى أرسل هاديين العقل والرسول، والعقل متقدم على\nالرسول من حيث أنه بالعقل يهتدي إلى معرفة الرسول، فقوله: (ضلوا)\nإشارة إلى ضلالهم عن مقتضى العقل وضلوا عن سواء السبيل إلى ما أتى به النبي - صلى الله عليه وسلم -."}, {"a": [78], "v": 5, "p": 416, "ev": 5, "ep": 417, "sid": 1908, "t": "قوله عز وجل: (لعن الذين كفروا من بني إسرائيل على لسان داوود وعيسى ابن مريم ذلك بما عصوا وكانوا يعتدون (78)\nالاعتداء والتعدي والعدوان خروج عما حد ورسم،\nإن قيل: على أي وجه لعنوا على ألسنتهما؟\nقيل في ذلك أوجه: الأول: أنهم فعلوا ما استحقوا به اللعن\nفلعناهم بأسمائهم، وذلك راجع إلى آبائهم، فقد روي أن\n⟦5:417⟧\nداوود بلغه أن قوما اجتمعوا على منكر فقصدهم ليعظهم فاستفتحهم الباب فلم يفتحوا وقالوا: نحن قردة، فقال: كونوها فمسخهم قردة، وإن قوما آذوا عيسى عليه الصلاة والسلام فلعنهم،\nالثاني: أنهما قالا: من لم يفعل كذا فلعنة الله عليه، فعصو، فصاروا ملعونين من هذا الوجه.\nالثالث: أن الله تعالى لما أنزل على كل واحد منهما كتابا اقتضى أن من خالفه فهو ملعون، فخالف هؤلاء، فصاروا من هذا الوجه ملعونين."}, {"a": [79], "v": 5, "p": 417, "ev": 5, "ep": 418, "sid": 1909, "t": "قوله عز وجل: (كانوا لا يتناهون عن منكر فعلوه لبئس ما كانوا يفعلون (79)\nالتناهى: أن ينهى بعضهم بعضا، والانتهاء الانزجار، وهو أبلغ من الانتهاء\n⟦5:418⟧\nوالمعنى لم يكونوا ينتهون، ولا يتناهون عن القبح الذي أناطوه، ثم ذم فعلهم."}, {"a": [80], "v": 5, "p": 418, "ev": 5, "ep": 418, "sid": 1910, "t": "قوله عز وجل: (ترى كثيرا منهم يتولون الذين كفروا لبئس ما قدمت لهم أنفسهم أن سخط الله عليهم وفي العذاب هم خالدون (80)\nأى ترى كثيرا من الذين لعنوا موالين للكفار في محاداة الرسول - صلى الله عليه وسلم - وذلك يجر إليهم سخط الله ويدخره لهم وبئس المدخر سخطه تعالى وما يثمر لهم الخلود في العذاب ونحو قوله: ﴿بِئۡسَمَا ٱشۡتَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡ أَن يَكۡفُرُواْ بِمَآ أَنزَلَ ٱللَّهُ بَغۡيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ﴾⟪2:90⟫."}, {"a": [81], "v": 5, "p": 418, "ev": 5, "ep": 419, "sid": 1910, "t": "قوله عز وجل: (ولو كانوا يؤمنون بالله والنبي وما أنزل إليه ما اتخذوهم أولياء ولكن كثيرا منهم فاسقون (81)\nالنبي يجوز أن يكون إشارة إلى نبينا عليه الصلاة والسلام\nويجوز أن يكون إشارة إلى نبيهم، ونبه أنهم لو آمنوا بمن ادعوا الإيمان به\nلما فعلوا ما فعلوا، فإن دينهم لا يقتضي ما يرتكبونه ويفعلونه،\nويجوز أن يكون النبي إشارة إلى الجنس، أي الإيمان بالله وبالنبوة والكتاب، لا يقتضي ما يتحرونه من مولاة الكفار.\n⟦5:419⟧\nإن قيل : فكيف قال: ﴿وَلَٰكِنَّ كَثِيرٗا مِّنۡهُمۡ فَٰسِقُونَ﴾⟪5:81⟫ بل كافرون؟\nقيل الإشارة: ﴿وَلَٰكِنَّ كَثِيرٗا مِّنۡهُمۡ﴾⟪5:81⟫ أي أحبارهم وعلمائهم\nوأماثلهم، فيشير إلى أن فسق هؤلاء هو الذي اقتضى أن يرتكب\nجماعتهم ما يرتكبونه وذلك لما أنبا بقوله: ﴿كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ﴾⟪5:79⟫."}, {"a": [82], "v": 5, "p": 419, "ev": 5, "ep": 421, "sid": 1911, "t": "قوله عز وجل: (لتجدن أشد الناس عداوة للذين آمنوا اليهود والذين أشركوا ولتجدن أقربهم مودة للذين آمنوا الذين قالوا إنا نصارى ذلك بأن منهم قسيسين ورهبانا وأنهم لا يستكبرون (82)\nأصل العدواة المباعدة ومنه يعدي والعدا للمكان المتفاوت.\nوالقس والقسيس: العابد الكثير الذكر.\nوالرهبان جمع راهب كالركبان والفرسان جمع راكب وفارس،\nبين أنه كما بين الأخيار تفاوت كذلك بين الأشرار تفاوت،\nوكما أن من أتى من\n⟦5:420⟧\nالطاعة ما هو أدنى كان ثوابه أدنى، كذلك من أتى من المعصية أكثر كان\nعقابه أكثر، ولهذا جعل في الجنة درجات، وفي النار دركات، فالله لا يبخس عاملا عمله. فلا يساوي بين من جحده وبين من يؤمن به ولا يكفر بأنبيائه، ولا بين من يجحد جميع أنبيائه، وبين من يجحد بعض أنبيائه فالمشركون به أبعد من الله من اليهود، واليهود أبعد من النصارى وإن أبعد الناس عن الإسلام اليهود والمشركون، أما اليهود فلأنهم بعدوا عن المسلمين بدرجتين إذ قد كفروا بعيسى ومحمد عليهما الصلاة والسلام.\nوأما المشركون فلأنهم بعدوا بدرجات إذ قد جحدوا التوحيد والنبوات.\nإن قيل فلم قدم ذكر اليهود والمشركون شر منهم؟\nقيل: لأن الآية المتقدمة في ذكرهم، والقصد كان إليهم، فكان\nتقديمه لذلك أولى.\nوبين أن أقرب الناس إليهم قوم ادعوا التنصر ليس ذلك إشارة إلى جماعة النصارى بل قوم منهم.\nولهذا قال: ﴿ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰۚ﴾⟪5:82⟫.\nويدل على ذلك ما روي في التفسير\n⟦5:421⟧\nأن ذلك إشارة إلى النجاشى، وأصحابه الذين آمنوا من بعد. ثم بين أن\nمنهم القسيسين والرهبان وأنهم يتحرون الحق ولا يستكبرون عن قبوله والضمير في (أنهم) راجع إلى القسيسين والرهبان، وقيل: راجع إلى المعنيين بالدين كلهم."}, {"a": [83], "v": 5, "p": 421, "ev": 5, "ep": 422, "sid": 1913, "t": "قوله عز وجل: (وإذا سمعوا ما أنزل إلى الرسول ترى أعينهم تفيض من الدمع مما عرفوا من الحق يقولون ربنا آمنا فاكتبنا مع الشاهدين (83)\nالفيض سيلان عن امتلاء وأفضا لسيلانه وفاضته دمعة إذا امتلأت العين ثم سالت، وعنه اسستعير خبر مستفيض، وأفاض القوم من عرفه، فذكر تعالى أنهم يبكون ويؤمنون بالنبي عليه الصلاة والسلام، ويتضرعون إلى الله أن يجعلهم من جملة من وصفهم بقوله:\n⟦5:422⟧\n﴿وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ﴾⟪2:143⟫\nومعنى (فاكتبنا) أي اجعلنا منهم وثبتنا في جملتهم."}, {"a": [84], "v": 5, "p": 422, "ev": 5, "ep": 422, "sid": 1914, "t": "قوله عز وجل: (وما لنا لا نؤمن بالله وما جاءنا من الحق ونطمع أن يدخلنا ربنا مع القوم الصالحين (84)\nكأنه قيل لهم: لم آمنتم به؟ فقالوا: ولم لا نؤمن أي نصدق بالله وبالحق الذي جاءنا.\nوقوله: (ونطمع) من جملة قوله: ﴿وَمَا لَنَا﴾⟪5:84⟫،\nويجوز أن يكون استئنافا، وأن يكون في موضع الحال،\nأي لما لا نؤمن طامعين في أن يجعلنا ربنا من الصالحين\nوذلك إشارة إلى قوله: (فأولئك مع الذين أنعم الله عليهم من النبيين والصديقين والشهداء والصالحين وحسن أولئك رفيقا (69)."}, {"a": [85, 86], "v": 5, "p": 423, "ev": 5, "ep": 423, "sid": 1915, "t": "قوله عز وجل: (فأثابهم الله بما قالوا جنات تجري من تحتها الأنهار خالدين فيها وذلك جزاء المحسنين (85) والذين كفروا وكذبوا بآياتنا أولئك أصحاب الجحيم (86).\nقد تقدم ما هو تفسير لهذا ودل قوله: ﴿وَذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ﴾⟪5:85⟫ أنهم محسنون واستحقوا ذلك تنبيها أن ذلك\n....\n(1).\nفإن قيل: فمن المحسنين من لا يجزى فهو الذي إساءته أكثر؟\nقيل: المحسن المطلق هو الذي لا يستحق أن يوصف بضده ويكون وصفه بالحسن مطلقا، ووصفه بالإساءة مقيدا، فأما من إساءته موفية على إحسانه فلا يطلق عليه اسم الحسن."}, {"a": [87], "v": 5, "p": 423, "ev": 5, "ep": 425, "sid": 1915, "t": "قوله عز وجل: (يا أيها الذين آمنوا لا تحرموا طيبات ما أحل الله لكم ولا تعتدوا إن الله لا يحب المعتدين (87)\nلما ذكر حال الذين قالوا: - إنا نصارى، وذكر أن منهم قسيسين ورهبانا فمدحهم بذلك، وكانت الرهبانية قد حرموا على أنفسهم طيبات قد أحلها الله\n⟦5:424⟧\nلهم، ورأى تعالى قوما سوقوا إلى حالهم وهموا أن يقتدوا بهم حتى رأوا أن قوما من أصحابه عليه الصلاة والسملام همو بإخصائهم، هموا أن يفعلوا فعلهم ، وبين ما دل على ما قال: (بعثت بالحنيفية السهلة)،\nوقوله: ﴿وَلَا تَعۡتَدُوٓاْۚ﴾⟪5:87⟫\n⟦5:425⟧\nيجوز أن يكون حكما لما دل عليه قوله: ﴿لَا تُحَرِّمُواْ طَيِّبَٰتِ﴾⟪5:87⟫ وأن\nلا تعتدوا إلى تناول المحظورات، وتكون الآية نهيا عن الطرفين في التفريط والإفراط وحملا على القصر المذكور في قوله: ﴿وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا﴾⟪2:143⟫. ونحو ذلك من الآيات، وبين أنه لا يحب المعتدين، أي\nالاعتداء مناف لمرضاة الله،\nفإن قيل: ولم لم يقل والله يبغض المعتدين ليكون أبلغ؟\nقيل: بل قوله: ﴿لَا يُحِبُّ﴾⟪5:87⟫ أبلغ من وجه؛ لأن من المعتدين من\nلا يوصف بأن الله يبغضه ويوصف بأنه لا يحبه، وهو من لم يكن اعتداءه كبيرة، وكل مبغض غير محبوب، وليس كل من لا يكون محبوبا علته مبغضا. قال بعضهم: معنى ﴿لَا تُحَرِّمُواْ طَيِّبَٰتِ﴾⟪5:87⟫ أي لا تخلطوا مالكم من الحلال\nبمغصوب، ولا تفعلوا فيه فعلا يصير به حراما، فتكونوا قد جعلتم الحلال\nحراما."}, {"a": [88], "v": 5, "p": 425, "ev": 5, "ep": 426, "sid": 1917, "t": "قوله تعالى: (وكلوا مما رزقكم الله حلالا طيبا واتقوا الله الذي أنتم به مؤمنون (88)\nالرزق: يقال لما جعل غذا، ويقال\n⟦5:426⟧\nللعطية جميعا، وقوله تعالى: ﴿وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا﴾⟪11:6⟫ أي ما يتغذى به، ﴿وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ﴾ أي مما أعطيناهم، ولتردد هذه اللفظة بين المعنيين اختلفوا أن ما رزق الله العبد هل يصح أن يكون حراما؟\nقال بعضهم هذه الآية يقتضي أن الرزق يقع على الحرام\nأيضا لأنه خص فقال: ﴿مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗاۚ﴾⟪5:88⟫ فلولا أنه يتناولهما\nلما كان لتخصيصه فائدة، وقال مخالفة قوله: ﴿حَلَٰلٗا طَيِّبٗاۚ﴾⟪5:88⟫ انتصابه على أنه\nحال مؤكدة كأنه قيل: كلوا مما رزقكم الله فهو حلال طيب،\nوبين أن الله الذي آمنتم به حثكم أن تتقوه فتمام الإيمان التقوى."}, {"a": [89], "v": 5, "p": 426, "ev": 5, "ep": 435, "sid": 1918, "t": "قوله تعالى: (لا يؤاخذكم الله باللغو في أيمانكم ولكن يؤاخذكم بما عقدتم الأيمان فكفارته إطعام عشرة مساكين من أوسط ما تطعمون أهليكم أو كسوتهم أو تحرير رقبة فمن لم يجد فصيام ثلاثة أيام ذلك كفارة أيمانكم إذا حلفتم واحفظوا أيمانكم كذلك يبين الله لكم آياته لعلكم تشكرون (89)\n⟦5:427⟧\nاللغو واللغي : ما لا يعتد به من المقال والفعال ومن هذا قيل: لصوت العصافير اللغو، وقيل ألغيت كذا أي طرحته لقلة الاعتداد به.\nواللغو في اليمين، روت عائشة أن رسول الله - صلى الله عليه وسلم -\nقال: (هو قول الرجل لا والله وبلى والله) موقوفا عليها.\n⟦5:428⟧\nوقال ابن عباس: - هو أن يحلف على أمر يراه كذلك وليس على ما يراه، وروي عنه أنه قال: هو أن تحلف البت على شيء وأنت غضبان،\nوقال بعضهم: - هو أن يحلف الرجل على معصيته بأن يفعلها فينبغي أن لا يفعلها قال وهذا لا كفارة فيه، لقوله عليه الصلاة والسلام:\n(من حلف على يمين فرأى أن غيرها خيرا منها فليركها، فإن تركها كفارتها) وقيل: بل لا إثم في تركها وعليه الكفارة، لقوله عليه الصلاة والسلام:\n(من حلف على شيء فرأى غيره خيرا فليأت الذي هو خير وليكفر عن يمينه) القسم ضربان: قسم على ماضي، وقسم على مستقبل،\nفالماضي: إما لغو وإما غموس، ولا كفارة فيها عند أبي حنيفة.\nوأما عند الشافعي ففي الغموس الكفارة دون اللغو.\n⟦5:429⟧\nقوله: ﴿وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ﴾⟪2:225⟫، يعني عند الشافعي: مؤاخذة\nالآخرة أي العقاب، والمؤاخذة بالكفارة عند أبي حنيفة مؤاخذة العقاب دون\nالكفارة، واختلف في الكفارة على أوجه، أما في الإطعام فقد اختلف فيه:\nهل الأولى أن يجمعوا على إطعامهم أو يدفع إليهم، فإذا جمعوا عليه فهل يطعمون وجبه أو يطعمون غداء وعشاء، وإذا أعطوا كم يعطون؟\nقال الحسن: يعطي كل مسكين نصف صاع من بر.\nوقال بعضهم: نصف صاع بر، وصاع من تمر.\n⟦5:430⟧\nوقال ابن عباس وابن عمر رضى الله عنه الله عنهما: بل مد من بر وهو\nقول مالك والشافعي، وقال سعيد بن جبير: مدان، مد لطعامه، ومد\nلإدامه، ولا خلاف أن الذكر والأنثى في ذلك سواء، وذكر اللفظ (عشرة)\nتغليبا للمذكر،\nوقوله: ﴿مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ﴾⟪5:89⟫\nقيل: هو راجع إلى مرات الإطعام، وقيل: هو راجع إلى جنس الطعام، وقيل: راجع إلى قدر ما يطعمون إن أطعم أهله مدا فمدا ، وإن أطعمهم صاعا فصاعا.\n⟦5:431⟧\nوأما الكسوة: فقد قيل: لكل مسكين ثوب إزار ورداء،\nوقال مالك: - يكسوا الرجل ثوبا والمرأة درعا وخمارا، فذلك أقل ما يجزي فيه الصلاة.\nقال الشافعي: يجزي منها قطعة من سراويل وعمامة ومقنعه.\nوأما تحرير الرقبة\n⟦5:432⟧\nفإيقاع الحرية عليه، وتخصيص لفظ الرقبة، فقد قيل: ذلك لأنهم كانوا إذا\nأسروا أسيرا شدقه إلى عنقه فإذا خلي قيل: حرر رقبته، فصار ذلك عبارة عن العتق، وحق المعتق أن لا يكون به عيب يضر بعمله كالعمى والشلل.\nفأما العور فإنه لا يضر، وقيل: يكره عتق المختل، ولا يجوز عتق الصبي\nالصغير، قال سليمان بن موسى: الرقبة لا تقع إلا على الكبير، فأما الصغير\nفيقال له النسمة، وقال إبراهيم: كل موضع في الشرع ذكر فيه رقبة\n⟦5:433⟧\nمؤمنة فإنه لا يجزئ إلا الذي صام وصلى، أي بلغ.\nوقوله: ﴿فَمَن لَّمۡ يَجِدۡ﴾⟪5:89⟫ أي لم يجد فضلا عن قوت عياله في يومه وليلته، فإن له أن يكفر بالصيام.\nوقال قوم: إذا لم يكن عنده مائتا درهم.\nوأما الصوم فقد قيل: متتابعات، ولذا قرأ أبي - رضي الله عنه -\n(فصيام ثلاثة أيام متتابعات)، واعتبر ذلك أبو حنيفة في الحكم،\nوإن كانت التلاوة منسوخة.\nوقال بعض الشافعية: قواه ذلك كفارة الحكم.\n(إذا حلفتم) يدل على\n⟦5:434⟧\nأن له أن يكفر إذا حلف قبل أن يحنث، ولم يقل إذا حنثتم.\nوقوله: ﴿وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ﴾⟪5:89⟫ أي أقلوا منها ولا تبذلوها لا للغوها، ولا ما يؤخذ بيمين اللغو، وإن لم يؤخذ به فقد يودي بالإنسان إلى أن يتعود إكثار اليمين، وقيل معناه: إذا حلفتم فلا تنقضوها،\nكقوله: ﴿وَأَوۡفُواْ بِعَهۡدِ ٱللَّهِ إِذَا عَٰهَدتُّمۡ﴾⟪16:91⟫ وقوله: ﴿أَوۡفُواْ بِٱلۡعُقُودِۚ﴾⟪5:1⟫\nوالصحيح أن الآية تتناول الأمرين - جميعا\nوعلى هذا قول الشاعر:\nقليل الألايا حافظ ليمينه ... وإن سبقت منه الألية برت!\nوجملة الأمر أن الإنسان مندوب إلى أن لا يحلف، ومن حلف على أن\n⟦5:435⟧\nلا يفعل فعلا يجب أو يستحب أن يفعل فحقه عليه أن لا يحنث،\nومن حلف على ما يجب أن لا يفعل أو يستحب أن يحنث في يمينه ويكفر،\nومن حلف على ما يجب أن لا يفعل أو يستحب أن يفعل، فاستوى فعله وتركه، فإن شاء حنث وكفر، وإن شاء حفظ اليمين.\nوقوله: ﴿كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ﴾⟪5:89⟫ أي أعلام دينه، أحكامه الدنيوي والأخروي، رجاء أن يعرفوه حق المعرفة، فإذا عرفتموه وفعلتم ما أمرتم يكونون أقرب إلى أن توفوا حق شكره."}, {"a": [90], "v": 5, "p": 435, "ev": 5, "ep": 437, "sid": 1927, "t": "قوله عز وجل: (يا أيها الذين آمنوا إنما الخمر والميسر والأنصاب والأزلام رجس من عمل الشيطان فاجتنبوه لعلكم تفلحون (90)\nالنجس والرجس والرجز متقارب، لكن النجس يقال فيما يستقذر بالطبع، والرجس أكثر ما يقال فيما يستقذر بالفعل ولهذا فسر بالإثم والسخط. والخمر بالاتفاق: عصير العنب المشتد، وقد يسمى نقيع البسر والتمر خمرا،\n⟦5:436⟧\nقال ابن عباس: نزل تحريم الخمر وهي الفضيح، وروى النعمان بن\nبشير عن النبي - صلى الله عليه وسلم - (إن من الحنطة خمرا، ومن الشعير خمرا، ومن الزبيب خمرا، ومن التمر خمرا، ومن العسل خمرا)\nوهذا يدل على خلاف ما قال أبو حنيفة.\nوقوله عليه الصلاة والسلام: (الخمر هاتين الثسجرتين من\nالنخل والعنب) فإنه لا يقتضي أن لا يكون من غيرهما، وقوله عليه الصلاة\nوالسلام: (كل مسكر حرام)، يقتضي تحريم ذلك جميعا، سواء أسكر\nومن شأنه أن يسكر؛ لأن اسم الفاعل حقيقة في الماضى والحال والمستقبل، وقد تقدم الكلام في تحريم الخمر في سورة البقرة.\nالميسر الضرب\n⟦5:437⟧\nبالقداح على الجزور، وسمي بذلك اعتقادهم أنه سبب يسار الفقر لما ينالهم من لحمه، وقال أمير المؤمنين: - الشطرنج من الميسر، وقيل:\nالقمار كله منه أي حكمه حكمه.\nوالأنصاب ما نصب للعبادة من الأوثان،\nوقيل كان حجرا بين يدي الصنم يذبح عليه،\nوعلى هذا قال الشاعر:\n......\nوما هريق على الأنصاب من جسد\nوالأزلام: قداح يكتب على بعضها افعل، وعلى بعضها لا تفعل،\nأو يكتب عليها حسن أو مذموم، فكانوا إذا أرادوا أمرا ضربوه\nواعتمدوه فيما يفعلونه،\nوقوله: ﴿مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ﴾⟪5:90⟫ أي من تربيته."}, {"a": [91], "v": 5, "p": 437, "ev": 5, "ep": 438, "sid": 1929, "t": "قوله عز وجل: (إنما يريد الشيطان أن يوقع بينكم العداوة والبغضاء في الخمر والميسر ويصدكم عن ذكر الله وعن الصلاة فهل أنتم منتهون (91)\n⟦5:438⟧\nلما كان هذان يتولد منهما العدواة خصهما بإعادة ذكرهما،\nفأما الأنصاب فإنها سبب الكفر المحض، وهذه العلة في الخمر تقتضي\nمشاركة البنية إياها.\nإن قيل: الذي يصد عن ذكر الله هو شرب الكثير دون\nالقليل، فحسبه أن يكون هو المحرم؟\nقيل: بل ذلك منهما فإن القليل داع من شربه إلى الكثير، وشرب الكثير داع إلى ذلك بلا واسطة.\nوقوله: ﴿فَهَلۡ أَنتُم مُّنتَهُونَ﴾⟪5:91⟫ نهاية الردع والزجر."}, {"a": [93], "v": 5, "p": 439, "ev": 5, "ep": 442, "sid": 1931, "t": "وقوله عز وجل: (ليس على الذين آمنوا وعملوا الصالحات جناح فيما طعموا إذا ما اتقوا وآمنوا وعملوا الصالحات ثم اتقوا وآمنوا ثم اتقوا وأحسنوا والله يحب المحسنين (93)\nروى أنه لما نزلت الآية الأولى قال: قد مات منا عدة، يشربون الخمر فما حالهم؟ فأنزل الله هذه الآية،\nروى أنها نزلت: في قوم كانوا قد حرموا على أنفسهم المباحات،\nوروى أن قدامة ابن مظعون شرب الخمر فأراد عمر أن\n⟦5:440⟧\nيجلده، فتلا قدامة هذه الآية، فقال عمر: أخطأت التأويل، إذا أيقنت واجتنبت ما حرم الله عليك.\nإن قيل ما الفرق بين الإيمان والتقوى والحسنى؟\nقيل: الإيمان: - هو الإذعان للحق على سببيل التصديق له بالتبيين.\nهذا وإن كان في المتعارف صار اسما للتخصيص بشريعة نبينا - صلى الله عليه وسلم -.\nوبالتقوى: - جعل اليقين وقاية من السخط بالانتهاء عما نهى، والإتيان بما أمر.\nوالإحسان: تحري الأفعال الجميلة في الإيمان والتقوى، ولهذا قال عليه الصلاة والسلام: لما قيل له: ما الإحسان؟ فقال: (أن تحبد الله كأنك تراه) وثالثهما مرتبة وإن كان لكل واحد مراتب.\nإن قيل ظاهر الآية يقتضى أن المؤمن المتقي المحسن يجوز له أن يتناول ما يريد تناوله والجناح عنه مرفوع، قيل: رفع الجناح عنه، لا لأنه\n⟦5:441⟧\nأبيح له ما حظر على غيره، بل لأنه أمن أن يأتي بما هو محظور، وهذا كقولك: لن أمنت أن يتعدى طوره لا بأس عليك فيما صنعته، ولا حجر عليك\nفيما أردته وارتكبته، يعني أنك مأمون الغاية أن يتعدى طورك،\nفبين بالآية أن من صار بهذه المنزلة من الإيمان أحجم عن المحظور وعفي عنه، وعلى هذا قوله: ﴿قُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ﴾⟪7:32⟫ الآية.\nإن قيل: ما وجه تكرير ذكر الإيمان والتقوى؟\nقيل في ذلك أوجه:\nالأول: ليس من آمن واتقى فيما كان قد حرم عليه وقت إباحة الخمر وأدام الإيمان واستعمل التقوى، إلا أن في ترك شربه. ثم النهي في غير ذلك واستعمل الحسنى جناح فيما شربه من الخمر، وتعاطاه من الميسر، قبل أن يحرم ذلك.\nالثاني: لا جناح في تناول المباح من آمن واتقى فيما مضى، وفي الحال وفي المستقبل، فأما من ترك ذلك في أحد الحالين، ولم يقلع بتوبة فله الإثم.\nالثالث: أنه أراد استعمال الإنسان الإيمان والتقوى فيما بينه وبين نفسه، أو بينه وبين الناس، وبينه وبين الله.\n⟦5:442⟧\nالرابع: أن للإيمان والتقوى على القول المجمل ثلاثة منازل:\nإما أن يكون الإنسان في أوله وأوسطه أو في منتهاه، وكذا الفسق ثلاث\nمنازل، كما قال: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا﴾⟪4:137⟫ فبين أن الإنسان إذا استوعب المنازل الثلاث فقد كمل\nوصار بحيث لا يتناول إلا المباح فلا جناح عليه لذلك فيما طعم.\nالخامس: أن للتقوى ثلاث منازل:\nالأول: ترك المحرمات،\nالثاني: ترك الشبهات،\nالثالث: ترك بعض المحللات تهذيبا لنفسه، لا تحريما ومن بلغ هذا\nالمبلغ فلا جناح عليه فيما يتناوله بعد ذلك،\nوبين بقوله: ﴿وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ﴾⟪5:93⟫ أن من فعل ذلك فقد صار محسنا،\nوإذا صار محسنا صار لله محبوبا فإن الله يحب المحسنين."}, {"a": [94], "v": 5, "p": 442, "ev": 5, "ep": 444, "sid": 1934, "t": "قوله تعالى: (يا أيها الذين آمنوا ليبلونكم الله بشيء من الصيد تناله أيديكم ورماحكم ليعلم الله من يخافه بالغيب فمن اعتدى بعد ذلك فله عذاب أليم (94)\n⟦5:443⟧\nالابتلاء: - استخراج ما عند الإنسان من البلاء، أي الفعل كالاختيار في كونه استخراج خبر الإنسان،\nوقوله: ﴿بِشَيۡءٖ مِّنَ ٱلصَّيۡدِ﴾⟪5:94⟫ قيل: - (من) للجنس أي بصيد البر دون البحر وصيد الإحلال دون الإحرام،\nوقيل للتبيين لقوله: ﴿فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ﴾⟪22:30⟫،\nوقيل: للتبعيض أي من أجر الصيد ما يمكن اصطياده ،\nوقوله: ﴿تَنَالُهُۥٓ أَيۡدِيكُمۡ﴾⟪5:94⟫ أي ما كان مستأنسا منه،\nوقيل: فراخ الطيور، وصغار الوحش والبيض،\nفقد روي: (أنه أتى النبى - صلى الله عليه وسلم - بيضتان\n⟦5:444⟧\nفامتنع منهما، وقال: (محرمون)، وقضى عليه الصلاة والسلام في بيض\nنعام أصابها محرم ثمنه، وما تناله، وما حكمه هي الممتنعات، ولم يعن الرماح فقط بل عناها وسائر الأسلحة، أي جعل تعالى ذلك ليكون ذريعة إلى ظهور أفعالكم وما يستحقون به الجزاء،\nوقيل: إن قوله: (ليبلونكم) أي يوجب الله تعالى ذلك عليكم لترضوا به\nأنفسكم، وتتوصلوا إلى الامتناع عن محارمه الخفية، ليعلم بذلك كيف تضبطوا أنفسكم حتى لا يطلع عليكم غيركم وإنما يطلع عليه رب العزة، وذلك إشارة إلى خفيات القلوب والسرائر.\nوقوله: ﴿فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ﴾⟪5:94⟫ أي من تعدى في هذه الظواهر بعدما حظر عليه فيما ولا يراعي أمره فأولئك هم الذين يتعدون ويستحقون العذاب الأليم."}, {"a": [95], "v": 5, "p": 445, "ev": 5, "ep": 451, "sid": 1937, "t": "وقوله عز وجل: (يا أيها الذين آمنوا لا تقتلوا الصيد وأنتم حرم ومن قتله منكم متعمدا فجزاء مثل ما قتل من النعم يحكم به ذوا عدل منكم هديا بالغ الكعبة أو كفارة طعام مساكين أو عدل ذلك صياما ليذوق وبال أمره عفا الله عما سلف ومن عاد فينتقم الله منه والله عزيز ذو انتقام (95)\nذكر لفظ القتل دون الذبح والذكوة لأمرين:\nأحدهما: - أنه أعم الألفاظ في ذلك،\nوالثاني تنبيه أن ما يصيبه غير مذكي والصيد هاهنا\nمخصوص في كل متوحش يؤكل لحمه عند أكثر الفقهاء،\nبدلالة قول النبي عليه الصلاة والسلام: (خمس يقتلهن المحرم في الحل والحرم، الحية والفأرة والعقرب والكلب العقور)،\nوفي خبر آخر: (الذئب والفأرة والغراب والحدأة)،\n⟦5:446⟧\nوقيل نبه بقوله العقور على ما يؤذي.\nواختلف في الصيد بتذكية المحرم هل يأكله حلال؟\nفأجراه بعضهم: مجرى ذبح المجوسي والوثني،\nوأجراه بعضهم: مجرى ذبح الشاة المغصوبة، والذبح بالسكين المغصوب،\n(وأنتم حرم)، أي محرمون - بحج أو غيره، أو داخلون\nفي الحرم، وأجمعوا أنه لم يرد أنهم في الشهر الحرام، وإن كان اللفظ\nيحتمله، وقوله: (ومن قتله ومنكم متعمدا) فيه ثلاثة أقوال : -\n⟦5:447⟧\nالأول: ما روي عن ابن عباس: أن الكفارة لا تلزم المخطئ لتخصيص العمد.\nالثاني: ما روي عن مجاهد أنه إذا كان عامدا لقتله ناسيا لإحرامه فعليه\nالجزاء، وإن كان ذاكرا لإحرامه عامدا لقتله فلا جزاء عليه.\nالثالث: وهو الأكثر أن عليه الكفارة، على كل حال وتخصيص العمد بالذكر لقوله: ﴿وَمَنۡ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنۡهُۚ﴾⟪5:95⟫ وذلك تخصيص بالعامد دون المخطئ، وأكد ذلك بأن الأصول تقتضي المساواة بين العمد والخطأ فيما يختص بإتلاف المال.\n⟦5:448⟧\nوقوله: ﴿فَجَزَآءٞ مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ﴾⟪5:95⟫.\nقد تقدم أن المثل يقع على الند الذي هو مماثلة في الجنس،\nوعلى الشبه الذي مماثلة في الكيفية، وعلى المساواة التي هي\nالمماثلة في الكمية، وعلى المشاكلة التي هي المماثلة في الهيئة،\nفلما كانت المماثلة لا تختص، صار اللفظ مشتركا.\nفاختلف فيه فاعتبر ابن عباس: المماثلة في الخلقة،\nوإليه ذهب سعيد بن جبير وقتادة ومالك والشافعي،\nواعتبر عطاء ومجاهد المماثلة في القيمة،\nوإليه ذهب أبو حنيفة، وأبو يوسف.\nوقالوا: إن شاء اشترى بها طعاما، فأعطى كل مسكين مدا، وإن شاء صام عن كل نصف صاع يوما.\n⟦5:449⟧\nواللفظ بالأول أليق لقوله: ﴿مِنَ ٱلنَّعَمِ﴾⟪5:95⟫\nوفي الآية قراءتان: ﴿فَجَزَآءٞ مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ﴾⟪5:95⟫ بالتنوين، (وجزآء مثل)\nبالإضافة، فإذا قرأ بالتنوين فلأنه يجعل الجزاء اسما لا يجازى به مثل أي مماثل\nلما قتل.\nوقوله: ﴿مِنَ ٱلنَّعَمِ﴾⟪5:95⟫ في موضع الوصف للجزاء.\nقيل: هو أجود من الإضافة فإن الواجب هو جزاء المقتول من الصيد، لا جزاء مثل المقتول،\nفإن قيل: المقتول ليس بمقتول فيكون له جزاء، وإذا أضيف جزاء إلى مثل، فذكر المثل هاهنا كما من نحو أنا أكرم مثلك وجعلنا أكرمك،\nوقوله: ﴿يَحۡكُمُ بِهِۦ ذَوَا عَدۡلٖ﴾⟪5:95⟫ أي يجب أن يحكم بذلك عدلان،\nوروى قبيصة بن جابر قال:\n⟦5:450⟧\nابتدرت أنا وصاحب لي ظبيا فأصبته فأتيت عمر بن الخطاب فذكرت ذلك له\nفأقبل على رجل إلى جنبه فنظرا في ذلك فأتيت صاحبي وقلت إن عمر لم يدر لم يحكم حتى جمع صاحبا له، فسمع ذلك عمر، فأقبل على ضربا بالدرة، وقال أما سمعت ﴿يَحۡكُمُ بِهِۦ ذَوَا عَدۡلٖ﴾⟪5:95⟫ وهذا ابن عوف وأنا ابن الخطاب.\nوقوله: ﴿أَوۡ عَدۡلُ ذَٰلِكَ صِيَامٗا﴾⟪5:95⟫\nقال الشافعي عنى عدل الهدي، وذاك أنه يقوم الهدي،\nوقال أبو حنيفة: عنى عدل الصيد فإنه يقوم الصيد،\nوقوله ﴿هَدۡيَۢا بَٰلِغَ ٱلۡكَعۡبَةِ﴾⟪5:95⟫ إخبار أنه لا يجوز نحر الهدي إلا في الحرم\n، واختلف في الطعام، هل يجوز غير في الحرم؟\nوقوله: ﴿عَفَا ٱللَّهُ عَمَّا سَلَفَۚ﴾⟪5:95⟫\n⟦5:451⟧\nأي عن قتل المحرم، وقيل: عن المرة الأولى،\nوقوله: ﴿وَمَنۡ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنۡهُۚ﴾⟪5:95⟫\nروي عن جماعة أنهم كانوا لا يحكمون على المحرم إذا أعاد\nإلى القتل الصيد وكان إذا استفتوا يقولون: هل جنيت شيئا قبل فإن قال:\nنعم، لم يحكموا عليه، وإن قال: لا، حكموا عليه،\nوقول فقهاء الأمصار أنه يحكم عليه بكل حال."}, {"a": [96], "v": 5, "p": 452, "ev": 5, "ep": 456, "sid": 1944, "t": "قوله عز وجل: (أحل لكم صيد البحر وطعامه متاعا لكم وللسيارة وحرم عليكم صيد البر ما دمتم حرما واتقوا الله الذي إليه تحشرون (96)\nالبحر: يتناول كلا مالحا كان أو عذبا، في جدول كان أو في نهر.\nقال تعالى: ﴿وَمَا يَسۡتَوِي ٱلۡبَحۡرَانِ هَٰذَا عَذۡبٞ فُرَاتٞ﴾⟪35:12⟫،\nوقوله: (وطعامه) أي ما قذف به البحر ميتا،\nوعلى ذلك قوله عليه الصلاة والسلام في البحر:\n(هو الطهور ماؤه الحل ميتته).\n⟦5:453⟧\nوالصيد هاهنا قيل: هو المصيد، وقيل: هو المصدر.\nفعلى الأول قال بعض العلماء: أكل المصيد على كل حال غير محظور.\n⟦5:454⟧\nواستدل بما روى أبو قتادة (أني أصبت حمار وحش فقلت:\nيا رسول الله: أصبت حمار وحش وعندي فضله، فقال كلوا فنحن\nحرم)،\nوعلى الثاني قال بعضهم: الاصطياد محرم، فأما أكل ما يصيد غيره\nفيجوز، واستدل على ذلك ما روي أنه قال عليه الصلاة والسلام:\n(وقد سئل عن الصيد فقال: (حلال لكم وأنتم حرم ما لم تصيدوا أو يصاد لكم).\n⟦5:455⟧\nفقال بعض العلماء: (وطعامه) أي ما يصاد له، قال: وهذا يدل على\nأن ما اصطاد المحرم أو صيد له من صيد البحر غير محرم عليه،\nقال الحسن (وطعامه) يعني البر والشعير ونحوهما مما يتغذى بالماء،\nوقيل : عنى ما مات فيه.\nوعليه دل قوله عليه الصلاة والسلام في البحر:\n(الطهور ماؤه الحل ميتته).\nوقيل: يتناول ذلك كل ما في البحر إلا ما استثناه السنة.\n⟦5:456⟧\nوقال بعضهم: - بل ذلك يتناول السمك فقط.\nوقوله: (متاعا) مصدر مؤكد، كقوله: ﴿كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ﴾⟪4:24⟫\nبعد قوله: ﴿حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ﴾⟪4:23⟫."}, {"a": [97], "v": 5, "p": 456, "ev": 5, "ep": 458, "sid": 1948, "t": "قوله عز وجل: (جعل الله الكعبة البيت الحرام قياما للناس والشهر الحرام والهدي والقلائد ذلك لتعلموا أن الله يعلم ما في السماوات وما في الأرض وأن الله بكل شيء عليم (97)\nالكعبة: بيت مربع شبيها مكعب ومنه قيل: كعب ثدي المرأة.\nوقوله: ﴿ٱلۡبَيۡتَ ٱلۡحَرَامَ﴾⟪5:97⟫ يصح أن يكون بدلا من قوله:\n⟦5:457⟧\n(الكعبة)، وقوله: (قياما) في موضع الحال، ويجوز أن يكون مفعولا\nثانيا، ويصح أن يجعل (البيت الحرام) مفعولا ثانيا، ويجعل (قياما)\nحالا، والقيام، والقوام ما يقوم به الأمر في معاشهم وصلاح أبدانهم،\nونقاء نفوسهم، ونبه تعالى أن الإنسان إذا تفكر فيها بين الله لهم من يعظم\nالكعبة أ. والشهر الحرام والهدي والقلائد.\nفنبهه بذلك أن الله تعالى لإحاطة علمه بالأشياء قبل كونها ومعرفته لمصالح العباد جعل ذلك سببا لعبادتهم لله تعالى،\nقال الأصم: (قياما للناس) أي: دائما لهم لا ينسخ حكمه،\nوقال الحسن: يعني بالشهر الحرام: الأشهر الحرم فأخرج اللفظ\nمخرج الواحد،\nفإن قيل ما فائدة قوله: ﴿وَأَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ﴾⟪5:97⟫ بعد\nقوله: ﴿مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ﴾⟪5:97⟫؟\nقيل: إن لفظ قوله: يعلم إخبار عن المستقبل ﴿وَأَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ﴾⟪5:97⟫\nأن ليس علمه مقصور على ما تقدم، بل هو عالم الغيب والشهادة،\nإن قيل: كيف جعل قياما علة لعلمنا أن الله يعلم ما في السموات والأرض؟\n⟦5:458⟧\nقيل: ليس هذا متعلق بل هو متعلق به وبما قبله.\nونبه أنه تعالى قيض إما باعث من خارج أو باعث من داخل على تحريم\nالقتال في الشهر الحرام، ولتعظيم الكعبة ليكون ذلك سببا لمصالح الناس التي من تفكر فيها علم أن الله فعله لعلمه بالخفيات."}, {"a": [98], "v": 5, "p": 458, "ev": 5, "ep": 458, "sid": 1950, "t": "قوله عز وجل: (اعلموا أن الله شديد العقاب وأن الله غفور رحيم (98)\nنبه بذلك أنه تعالى حيث سخر هذه الأمور وبينها دل ذلك أنه فعل ذلك لما أراده من عباده ليثيب المحسن ويعاقب المسىء، وذلك يقتضي أن يعلموا أنه يعاقب قوما ويرحي قوما كيفما تقتضيه حكمته."}, {"a": [99], "v": 5, "p": 458, "ev": 5, "ep": 458, "sid": 1950, "t": "قوله تعالى: (ما على الرسول إلا البلاغ والله يعلم ما تبدون وما تكتمون (99)\nالرسول المبعوث في أمر وأصله السائر على رسل، ومنه ترسل في القراءة إذا أمر فيه بلا تكلف، والرسل اللبن، وكأنه اسم\nللمرسل من الضرع كقولهم البعض، والبعث، والبلاغ: وصول المعنى\nإلى المقصود به، والبلاغة رابع يتصل به المعنى إلى النفس وفي هذا بلاغ كفاية يبلغ بها مقدار الحاجة، أي الرسول قد بلغ ما أمر وليس عليه أكثر من ذلك في أمر الرسالة ثم الله يتولى السرائر، كما قال عليه الصلاة والسلام: (إنما أقضي بينكم بالظاهر ويتولى الله السرائر)."}, {"a": [100], "v": 5, "p": 459, "ev": 5, "ep": 460, "sid": 1951, "t": "قوله تعالى: (قل لا يستوي الخبيث والطيب ولو أعجبك كثرة الخبيث فاتقوا الله يا أولي الألباب لعلكم تفلحون (100)\nالخبيث: هو الباطل في الاعتقاد. والكذب هو المقال الطالح في الفعال، وأصله الرديء الدخلة الذي تظهر ردأته في الاختيار ولهذا\nقال الشاعر:\nسبكناه ونحسبه لجينا ... فأبدى الكير عن خبث\nومتى اعتبر الطيب بالخبيث فهو كالدائرة من النقطة، بل كالشيء الذي\nلا قدرة له بالمرأى، فبين الله تعالى الطيب وإن استقللتموه فخير من الخبيث، وإن استكثر قوة حتى يعجبكم كثرة، ونبه أن الاعتبار في الأشياء ليس بالقلة والكثرة وإنما ذلك بالجودة والرداءة، فالمحمود القليل خير من الذميم الكثير، ولهذا قيل: أقلل وأطب.\n⟦5:460⟧\nإن قيل: كيف جعل الخبيث هاهنا كثيرا، وقد قال: (لا يغرنك تقلب الذين كفروا في البلاد (196) متاع قليل) فجعله قليلا،\nوقال: ﴿قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ﴾⟪4:77⟫؟\nقيل: استكثاره للخبيث هو على نظر المغترين بالدنيا،\nواستقلاله هو على ما عليه حقيقة الأمر.\nوقوله: ﴿وَلَوۡ أَعۡجَبَكَ﴾⟪5:100⟫ ليس بخطاب للنبي - صلى الله عليه وسلم - فقط بل هو خطاب لكل معتبر.\nكقول الشاعر:\nتراه إذا ماحييته سهلا ... كأنك تعطيه الذي أنت قائله\nولأجل أن الخطاب عام من حيث المعنى قال : ﴿فَٱتَّقُواْ ٱللَّهَ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ﴾⟪5:100⟫ بلفظ الجمع والمعنى استعملوا التقوى راجين أن تبلغوا الفلاح، تنبيها\nأن التقوى هى التي تبلغ."}, {"a": [101], "v": 5, "p": 460, "ev": 5, "ep": 466, "sid": 1952, "t": "قوله عز وجل: (يا أيها الذين آمنوا لا تسألوا عن أشياء إن تبد لكم تسؤكم وإن تسألوا عنها حين ينزل القرآن تبد لكم عفا الله عنها والله غفور حليم (101)\n⟦5:461⟧\nالبدو في القول: يقال تارة لظهوره، وتارة يقال لظهور تأويله وحقيقته. والعفو: يقال تارة لما يفضل عن الكفاية، كقوله: ﴿مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ﴾⟪2:219⟫\nأي ما فضل عن القوت، وتارة يقال لترك الشيء، قبل وجوبه كقوله عليه\nالصلاة والسلام: (عفوت لكم عن صدقة الخيل والرقيق).\nوتارة يقال لترك\n⟦5:462⟧\nما لزم فتجوفي عنه نحو ﴿فَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ﴾⟪5:13⟫،\nوروي عن النبي عليه الصلاة والسلام أنه خرج يوما غضبان وجلس على المنبر فقال: (لا أسأل عن شيء إلا أجبت، فقام رجل فقال أين أنا؟\nفقال: في النار، وقام آخر فقال: من أبي؟ فقال: حذافة، فقام عمر فقال: رضينا بالله ربا وبالإسلام دينا وبالقرآن إماما، والله يعلم من آباؤنا)، فنزلت هذه الآية.\nوقيل: إنه كان في الحج لما قال سراقة بن جعشم له عليه الصلاة والسلام: - أفي كل عام فقال عليه الصلاة والسلام: (لو قلت نعم لوجبت) الخبر.\n⟦5:463⟧\nوقيل: كان سؤالان في مجلس، وعلى هذا قال تعالى: - حكاية: ﴿فَلَا تَسۡـَٔلۡنِي عَن شَيۡءٍ حَتَّىٰٓ أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرٗا﴾⟪18:70⟫، وهذا في سؤال\nدون سؤال، وقوله: (أشياء) عند الكسائي بناها أفعال، قال: ولم\nيصرف تشبيها بحمراء، وهذا يلزمه أن لا يصرف أنباء، وعند الأخفش\nوالفراء أنها أفعلاء، ويلزمهما أن يصغر على شيئان وقد امتنع من ذلك، وعند\n⟦5:464⟧\nالخليل أنها فعلاء قلبوها، كما قلبوا أينق عن أنيق، وقسي عن قووس\nقوله: ﴿عَفَا ٱللَّهُ عَنۡهَاۗ﴾⟪5:101⟫ أي عن الأشياء المسؤول عنها، وقيل عن\nالمسألة، والقولان في التحقيق واحد.\nإن قيل ما موضع قوله: ﴿عَفَا ٱللَّهُ عَنۡهَاۗ﴾⟪5:101⟫ وما فائدة الإتيان بذلك؟\nقيل هو وصف لقوله: (أشياء) كأنه قيل لا تسألوا عن أشياء عفا الله عنها، أي لم يكلفكم السؤال عنها، كقوله عليه الصلاة والسلام: (عفوت لكم عن صدقة الخيل) أي لم أوجبها، وذاك لأن الأشياء في البحث عنها وسؤالها ثلاثة أضرب: ضرب يجب السؤال عنه:\n⟦5:465⟧\nوهو ما كلف به الإنسان، وفيه أمر وإياه توجه أن أفتي لجريج بالاغتسال\nفقال: (قتلتموه، هلا سألتم عنه، شفاء العيي السؤال)،\nوضرب يكره أو يحظر السؤال عنه، إياه توجه قوله عليه الصلاة والسلام: (اتركوني ما تركتكم، إنما هلك من كان قبلكم بكثرة سؤالهم الأنبياء)، وضرب يحبون السؤال عنه والسكوت عنه، وهو ما يحب أن يحمدوا\nلا يؤخذ به\n⟦5:466⟧\nالإنسان إن بحث عنه واستكشف.\nثم قال: ﴿وَٱللَّهُ غَفُورٌ حَلِيمٞ﴾⟪5:101⟫ أي غفور عنكم ما سبق منكم حليم لا يبطش بكم فيما ارتكبتم."}, {"a": [102], "v": 5, "p": 466, "ev": 5, "ep": 467, "sid": 1958, "t": "قوله عز وجل: (قد سألها قوم من قبلكم ثم أصبحوا بها كافرين (102)\nوالطلب والسؤال والاستخبار والاستفهام والاستعلام متقاربة\nومترتب بعضها على بعض، فالطلب أعمها، لأنه قد يقال فيما تسأله من غيرك، وفيما تطلبه بنفسك.\nوالسؤال لا يقال إلا فيما تطلبه من غيرك،\nفكل سؤال طلب، وليس كل طلب سؤالا،\nوالسؤال يقال في الاستعطاف، فيقال سألت فلانا كذا.\nويقال في الاستخبار، فيقال سألته عن كذا،\nوأما الاستخبار فاستدعاء الخبر،\nوذلك أخص من السؤال، وكل استخبار سؤال،\nوليس كل سؤال استخبارا.\nوالاستفهام طلب الإفهام وهو أخص من الاستخبار.\nفإن قول الله تعالى: ﴿ءَأَنتَ قُلۡتَ لِلنَّاسِ﴾⟪5:116⟫ استخبار، وليس استفهام وكل استفهام استخبار، وليس كل استخبار استفهاما.\nوالاستعلام: طلب العلم فهو أخص من الاستفهام،\nإذ ليس كل ما يفهم يعلم بل قد يظن، ويحتمل أن كل استعلام استفهام وليس كل استفهام استعلاما.\n⟦5:467⟧\nوقوله: ﴿قَدۡ سَأَلَهَا﴾⟪5:102⟫ نبه على وجهين:\nأحدهما: أنه استخبار، إشارة إلى نحو قوله لأصحاب البقرة حيث سألوا عن أوصافها، فعلى هذا لا فرق بين قوله: ﴿قَدۡ سَأَلَهَا﴾⟪5:102⟫ وبين قوله: قد سأل عنها.\nوالثاني: أنه استعطاف إشارة إلى نحو المستنزلين للمائدة من عيسى عليه الصلاة والسلام، والسائلين من صالح عليه الصلاة والسلام الناقة، فعلى هذا لا يصح أن يقال سأل عنها،\nوقوله: ﴿ثُمَّ أَصۡبَحُواْ بِهَا كَٰفِرِينَ﴾⟪5:102⟫ أي كفروا ولم يعترفوا،\nأو يعني كفروا تشبيها."}, {"a": [103], "v": 5, "p": 467, "ev": 5, "ep": 469, "sid": 1959, "t": "قوله عز وجل: (ما جعل الله من بحيرة ولا سائبة ولا وصيلة ولا حام ولكن الذين كفروا يفترون على الله الكذب وأكثرهم لا يعقلون (103)\nالجعل عام فيما يكون قولا وحكما، وفيما يكون عملا وصنعا،\nويكون تارة بمعنى صار، ولا يتعدى كقولك جعل فلان يقول كذا،\nوتارة بمعنى صير، ويتعدى إلى مفعولين كقولك: - جعلت الطين خزفا، وجعلت زيدا عدلا، أي حكمت بذلك،\nوتارة بمعنى فعل، ويتعدى إلى مفعول واحد، وعلى ذلك هذه الآية،\nوجعل بالجعل هو الحكم لإيجاد العين، فإن الله تعالى موجد هذه الأعيان، ولكنه غير حاكم فيها\n⟦5:468⟧\nبأحكامهم. فبين أن الله تعالى ما حكم بهذه الأحكام، ولكن الذين كفروا\nحكموا بذلك، وحكمهم بذلك لافترائهم على الله، وافترائهم على الله من حيث أن أكثرهم لا يعقلون، فجعل علة حكمهم بذلك افتراءهم على الله، وجعل علة افترائهم على الله كون أكثرهم لا يعقلون.\nإن قيل لما خص أكثرهم أنهم لا يعقلون؟\nقيل: إنه إشارة بذلك إلى ديانتهم المقلدة دون الذين علموا بطلان\nفعلهم لكن يمنعهم لرئاستهم أن يقلعوا عن ذلك مع معرفتهم ببطلانه.\nويجوز أن يكون ذلك إشارة إلى أماثلهم الذين يتبعون العقل وإن كانوا يعلمون ببطلان ما يفعلون.\nالبحيرة: - الناقة المشقوقة الأذن، وهي كل ناقة نتجت خمسة\nأبطن من كانت الخلقة أنثى شقوا أذفا فلا يجز لها وبر، ولا يذكر اسم الله\nعليها إن ذكيت، وحرم على النساء لبنها، وإن ماتت اشتركت الرجال والنسل في أكلها.\nوالسائبة: المسيبة وكان أحدهم ينذر، لأنه يخلص بناقته\n⟦5:469⟧\nشبيها، والوصيلة: الأنثى من الغنم إذا ولدت مع ذكر يقال: وصلت\nأخاها، فيذبحونه لآلهتهم.\nوالحامي: الفحل الذي ينتج من صلبه عشرة أبطن، وكان يقال حمى ظهره، فيسيب ولا يركب.\nقوله عز وجل: - (وإذا قيل لهم تعالوا إلى ما أنزل الله وإلى الرسول قالوا حسبنا ما وجدنا عليه آباءنا أولو كان آباؤهم لا يعلمون شيئا ولا يهتدون (104)\nقال أهل اللغة: أصل تعالي دعا إلى العلو، ثم استعمل في\nكل مكان علوا كان أو سفلا ، وقيل: إن ذلك يقال اعتبارا بالعلو الذي هو\nالمرتبة الرفيعة، فإذا قيل تعالي كأنه قيل اطلب بفعلك هذا علوا وشرفا كقولك لمن دعوته تفضل أي اطلب بذلك الفضل وانعم ونحو ذلك،\nثم كثر وصار كأنه موضوع المجرد.\nوالمعنى إذا دعوا إلى الكتاب والسنة أعرضوا وزعموا أنهم\nمكتفون بما شاهدوا عليه آبائهم كقوله: ﴿إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهۡتَدُونَ﴾⟪43:22⟫."}, {"a": [104], "v": 5, "p": 470, "ev": 5, "ep": 471, "sid": 1962, "t": "وقوله: ﴿أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ﴾⟪5:104⟫\nالألف دخل للتعجب من جهلهم أي أو يكفهم ذلك، وإن كان آباوهم\nلا يعلمون، فيفعلون ما يقتضيه علمهم ولا يهتدون بمن له علم،\nوأشير بأنهم من جملة الفرقة الثالثة الذين وصفوا فيما روي:\n(الناس عالم، وتعلم، وحائر نافر لا يطيع مرشدا).\nوقال على رضي الله عنه: (الناس ثلاثة: عالم رباني، ومتعلم\nعلى سبيل نحاه ونهج رعاع وأتباع كل ناعق يميلون مع كل ريح، لم يستضيئوا بنور العلم ولم يلجاؤا إلى ركن وثيق فيمتنعوا).\n⟦5:471⟧\nوقوله: ﴿لَا يَعۡلَمُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ﴾⟪5:104⟫ إشارة إلى أنهم هم الرعاع أتباع."}, {"a": [105], "v": 5, "p": 471, "ev": 5, "ep": 476, "sid": 1963, "t": "قوله عز وجل: (يا أيها الذين آمنوا عليكم أنفسكم لا يضركم من ضل إذا اهتديتم إلى الله مرجعكم جميعا فينبئكم بما كنتم تعملون (105)\nقيل لا يضركم ولا يضيركم من ضاره يضيره يضوره\nوجعل جوابا.\nولا يضركم الأجود أن يكون رفعا لا جوابا وإن جاز أن\nيكون في موضع الجزم على الجواب على معنى أنكم إن أصلحتم أنفسكم، ولم يتحروا ما فيه فسادكم وإفساد غيركم، لم يضركم فلا يكونا كمن قبلهم\n⟦5:472⟧\nليحملوا أثقالهم وأثقالا مع أثقالهم، وقوله: ﴿لِيَحۡمِلُوٓاْ أَوۡزَارَهُمۡ كَامِلَةٗ يَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيۡرِ عِلۡمٍۗ﴾⟪16:25⟫\nوليس في الآية حث على ترك النهي عن المنكر كما نقله قوم، فقد تقدم حث الله على ذلك في آيات كثيرة نحو قوله:\n﴿وَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ﴾⟪3:104⟫.\nوقال حاكيا عن لقمان: (يا بني أقم الصلاة وأمر بالمعروف وانه عن المنكر واصبر على ما أصابك إن ذلك من عزم الأمور (17).\nومدح القائلين بذلك فقال: ﴿ٱلۡأٓمِرُونَ بِٱلۡمَعۡرُوفِ وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَٰفِظُونَ لِحُدُودِ ٱللَّهِۗ﴾⟪9:112⟫.\nوقال عليه الصلاة والسلام: ((من رأى منكم منكرا واستطاع أن يغيره بيده\nفليغيره بيده فإن لم يستطع فبلسانه فإن لم يستطع فبقلبه)،\nويدلك على\n⟦5:473⟧\nذلك أنه قال: ﴿لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَيۡتُمۡۚ﴾⟪5:105⟫.\nومن الاهتداء إنكار المنكر.\nوقال أبو بكر - رضي الله عنه -: (إني أراكم تتناولون هذه الآية:\n(عليكم أنفسكم) وقد عهدنا رسول الله - صلى الله عليه وسلم - علمنا هذا على هذه الأمور وهو يقول: إن الناس إذا تركوا الأمر بالمعروف والنهي عن المنكر عمهم الله بعقابه)، وما بينكم وبين أن يعمهم بعقابه إلا أن تناولوا هذه الآية على غير تأويلها، وإنما المعنى لا تعتدوا بآبائكم واحفظوا أنفسكم أن تزل كما زل غيركم، وإذا اهتديتم فليس عليكم من ضلال من خالفكم شيء. كقوله: ﴿لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ﴾⟪2:272⟫،\n⟦5:474⟧\nوقوله: ﴿وَلَا تُسۡـَٔلُ عَنۡ أَصۡحَٰبِ ٱلۡجَحِيمِ﴾⟪2:119⟫.\nقيل: وفيها حث على أن نظر الإنسان لنفسه أن يهذب نفسه\nقبل أن يهذب غيره، وأن يعتبر حال نفسه قبل اعتبار حال غيره.\nوعلى هذا: ﴿قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا﴾⟪66:6⟫.\nفأمر أن يبدأ بنفسه.\nوقيل: إن ذاك إشارة إلى ترك النهي باليد واللسان، حيث يعلم أنه لا يغني ولا يجدي كما ورد في الخبر (إذا رأيتم هوى متبعا وإعجاب المرء بنفسه فعليكم أنفسكم).\n⟦5:475⟧\nوقيل: عنى من يضل من أهل الكتاب إذا التزموا الجزية، فيقول دعوهم وشأنهم\nولا يضركم منهم شيء، وقيل: إن ذلك إشارة إلى وقت مخصوص.\nفقد روي عن رسول الله - صلى الله عليه وسلم -:\n(ترك النهي إذا قدم كنيسة دمشق فجعل مسجدا، وإذا رأت الكاسيات العارية).\nقيل: هذا كان في زمن الوليد بن عبد الملك، فهو الذي هدم الكنيسة وضمها إلى المسجد.\n⟦5:476⟧\nوقال: مكحول وعبد الله بن مسعود: (عليكتم أنفسكم) إنما هو إذا غاب\nالواعظ وأنكر الموعوظ، وقيل: عنى بقوله: ﴿عَلَيۡكُمۡ أَنفُسَكُمۡۖ﴾⟪5:105⟫ أي\nلا تعتد بهؤلاء فيما يفعلونه من الشر وتركن إليهم وتستمرئ لنفسك ما تستمرئ لغيرك. كما يفعله كثير من الناس في أنهم يأخذون برخصهم فيؤدي ذلك بهم إلى الهلاك، وهذا كقولهم: كل شاة تناط برجليها.\nوقيل: إن ذلك توكيد لقوله: ﴿لَا تَسۡـَٔلُواْ عَنۡ أَشۡيَآءَ إِن تُبۡدَ لَكُمۡ تَسُؤۡكُمۡ﴾⟪5:101⟫ أي عليكم في أسئلتكم بما يعود منافعه عليكم لا يضاركم ولا يضركم كقولهم: - الحزم حفظ ما كلفت وترك ما كفيت.\nوقيل: معناه عليك نفسك فاشغلها قبل أن تشغلك\nفإن لم تصلحها أفسدتك."}, {"a": [106], "v": 5, "p": 476, "ev": 5, "ep": 483, "sid": 1968, "t": "قوله عز وجل: (يا أيها الذين آمنوا شهادة بينكم إذا حضر أحدكم الموت حين الوصية اثنان ذوا عدل منكم أو آخران من غيركم إن أنتم ضربتم في الأرض فأصابتكم مصيبة الموت تحبسونهما من بعد الصلاة فيقسمان بالله إن ارتبتم لا نشتري به ثمنا ولو كان ذا قربى ولا نكتم شهادة الله إنا إذا لمن الآثمين (106)\n⟦5:477⟧\nهذه الآية يتعلق بها حكم التقدير والإعراب والفقه، فأما تقديرها: فهو إذا حضر أحدكم الموت فشهادة بينكم اثنان ذوا عدل، أو إن ضربتم في الأرض فأصابتكم مصيبة الموت فآخران من غيركم إن لم يكن ذوا عدل منكم، فإن ارتبتم تحسبونهما من بعد الصلاة فيقسمان بالله لا نشتري به ثمنا، واستغنى عن جواب إذا حضر بقوله: ﴿شَهَٰدَةُ بَيۡنِكُمۡ﴾⟪5:106⟫، وعن جواب إن ضربتم، بقوله: ﴿أَوۡ ءَاخَرَانِ مِنۡ غَيۡرِكُمۡ﴾⟪5:106⟫، وعن جواب الفاء بقوله: ﴿تَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ﴾⟪5:106⟫، وقوله: (بالله) يصح أن يكون استئنافا فيكون هو الذي يتفوه\nبه المقسم على تقدير فيقسمان، ويقولان: - تالله لا نشتري.\nويجوز أن يكون متعلق بيقسمان، فيكون قوله: ﴿لَا نَشۡتَرِي﴾⟪5:106⟫ على تقدير: والله لا نشتري فهذا تقدير الآية.\nفأما إعرابها: فقوله: ﴿شَهَٰدَةُ بَيۡنِكُمۡ﴾⟪5:106⟫ يجوز أن يكون\nمبتدأ وخبره قوله: (اثنان) كأنه قيل: شهادة بينكم شهادة اثنين.\n⟦5:478⟧\nويجوز أن يكون تقديره: عليكم أن تشهد اثنان، فيكون قوله: (شهادة) ابتداء محذوف الخبر و (اثنان) مرتفع بقوله (شهادة).\nوقيل: يكون (شهادة بينكم) مبتدأ وقوله: (اثنان) فاعل، ويرتفع به، ويستغني عن خبر الابتداء كقولهم: - قائم الزيدان.\nوقوله: ﴿إِذَا حَضَرَ﴾⟪5:106⟫ خبر، لقوله: (شهادة)\nوقوله: ﴿حِينَ ٱلۡوَصِيَّةِ﴾⟪5:106⟫ بدل من قوله:\n﴿إِذَا حَضَرَ﴾⟪5:106⟫ وقيل هو ظرف لقوله: ﴿إِذَا حَضَرَ﴾⟪5:106⟫، وحضور الموت:\n⟦5:479⟧\nحضور أسبابه من المرض ونحوه.\nوقوله: ﴿أَوۡ ءَاخَرَانِ﴾⟪5:106⟫ ليس على التخيير، بل معناه: إنما يقبل الآخران في السفر خاصة، إذا عدم العدلان وأما فيهما فقد اختلف في قوله: ﴿أَوۡ ءَاخَرَانِ مِنۡ غَيۡرِكُمۡ﴾⟪5:106⟫ فقال بعض الفقهاء: إذا كان من غير قبيلتكم، ولم يعن من غير المسلمين، لأن شهادتهم لا تقبل علينا بوجه، ويقوي ذلك بقوله: ﴿تَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ﴾⟪5:106⟫ وقال إنما يفعل بمن في قلبه استعظام الصلاة فينزجر عن اليمين مخافة العقوبة، وإلى هذا ذهب الحسن.\nقوله: إنه أريد من غير قبيلتكم.\nوقال بعضهم عنى من غير المسلمين، قال والقصة التي نزلت الآية في سببها\n⟦5:480⟧\nيدل على ذلك، فهو أن تميما الداري وعديا، وكانا حينئذ نصرانيين\nبنجران فخرج معهما مولى لعمرو بن العاص يقال له بديل، ومعه متاع.\nفلما قدموا الشام مرض المولى وكان مسلما فكتب وصيته ولم يعلم بذلك تميم\nوعدي، وقدما المدينة، ودفعا المتاع إلى عمرو بن العاص، وأخبراه بموت\nبديل، فقال عمرو: ولقد توجه من عندنا بأكثر من هذا المتاع، فهل باع\nشيئا، فقالا: لا، فمضى بهما إلى النبي - صلى الله عليه وسلم - فأحلفهما أن بديلا ما ترك غير هذا، ثم إن عمرو بن العاص ظهر على آنية فضة عند تميم، فقال هذه الآنية لي وهى مما كان مع بديل، فقالا: كنا اشتريناها منه، فقال عمرو: لقد سألتكما\n⟦5:481⟧\nهل باع شيئا، قلتما: لا، فقالا: نسينا، فذهبوا إلى رسول الله - صلى الله عليه وسلم - فقالا: إنا كنا ابتعنا الآنية ولم يكن لنا عليه بينة فكرهنا أن نقر، فنزلت الآية على النبي - صلى الله عليه وسلم -، فعلى هذا شهادة أهل الذمة في الوصية في السفر يجوز إذا لم يوجد العدلان\nوقد حكم أبو موسى في مثله بذلك، وقال هذا حكم ثابت غير منسوخ.\nوقال بعضهم: - ذاك في الكافر في أول الإسلام ثم نسخ بآية\nالشهادة، ولا يجوز الآن شهادة الذمي على المسلم بوجه، وقد بينت أن لا يمين على الشاهد بوجه، ولا يجوز الارتياب على الشاهد لمكان اليمين، ولا يجوز\n⟦5:482⟧\nأيضا أن يجعل يمين الورثة معارضة ليمين الشاهد، فيجب أن يكون ذلك منسوخا بقوله: ﴿وَأَشۡهِدُواْ ذَوَيۡ عَدۡلٖ مِّنكُمۡ﴾⟪65:2⟫ ومن قال بالأول فقال بقوله:\n(فيقسمان) ليس بإيجاب، وإنما هي أن يبتدئ الشاهد فيحلف من غير أن\nيحلف، فذكر أنه لا يعرج على يمينه ولا يعتد به، وإنما كان منسوخا أن لو\nكان ذلك واجبا.\nإن قيل: لما قال: ﴿لَا نَشۡتَرِي بِهِۦ ثَمَنٗا﴾⟪5:106⟫ والثمن هو الذي يشتري به\nلا يشتري هو؟\nقيل: قد قال بعض أهل اللغة: - أراد ذا ثمن فحذف المضاف، وقيل: إن كل شراء بيع وليس كل بيع شراء، وذلك يختلف بالاعتقاد في الثمن والمثمن، ولهذا قيل: بعت واشتريت من الأضداد، فعلى هذا\nكأنه جعل الثمن مصورا بصورة البيع، فلهذا قيل ذلك وقد دل في موضع آخر: ﴿ٱشۡتَرَوۡاْ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلٗا﴾⟪9:9⟫.\nوقوله: ﴿وَلَوۡ كَانَ ذَا قُرۡبَىٰ﴾⟪5:106⟫ أي للميت، ولو كان المشهود قريبا وذلك لما في طبع الإنسان من ميله إلى أقاربه، ومن هذا الوجه رد شهادة الأب للابن، والابن للأب، وأضاف\n⟦5:483⟧\nالشهادة إلى الله تعظيما لها كقوله: ﴿وَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ﴾⟪65:2⟫.\nوقرأ\nالشعبي: ﴿وَلَا نَكۡتُمُ شَهَٰدَةَ﴾⟪5:106⟫ بالتنوين، وجعل الله مجرورا ومنصوبا\nعلى تقدير القسم."}, {"a": [107], "v": 5, "p": 483, "ev": 5, "ep": 486, "sid": 1975, "t": "قوله عز وجل: (فإن عثر على أنهما استحقا إثما فآخران يقومان مقامهما من الذين استحق عليهم الأوليان فيقسمان بالله لشهادتنا أحق من شهادتهما وما اعتدينا إنا إذا لمن الظالمين (107)\nقوله: (الأولين) يحتمل إعرابه أوجها:\nالأول: أن يكون مبتدأ وقوله: (فآخران) خبر.\nوتقديره: إن عثر أنهما استحقا إثما أي أن اطلع وقف على أن الشاهدين\nهما الآخران من غير أن يحيفا في شهادتهما فاستحقا إثما، فالأوليان آخران يقومان مقامهما من الذين استحق عليهم أي من أهل الميت،\nويجوز أن يكون قوله: (فآخران) مبتدأ، و (الأولين) خبره،\nويجوز أن يكون قوله:\n⟦5:484⟧\n(فآخران) مبتدأ و (يقومان) خبره، و (الأولين) بدل إما\nمن قوله: (فآخران) أو من الضمير في قوله: (يقومان) أو يكون\nخبر ابتداء مضمر، فهذه ستة أوجه في إعرابه،\nوقد أجاز أبو الحسن وجها سابعا: وهو أن يكون: (الأولين) صفة لقوله: (فآخران) قال: ويجوز ذلك، وإن كان قوله: (فآخران) و (الأولين)\nمعرفة، لأن ذلك تعريفه للجنس، وقوله: (فآخران) قد وصف، والنكرة\nالموصوفة قريبة من المعرفة بالألف واللام الدالة على الجنس،\nولهذا صح أن يوصف ما فيه الألف واللام بغيره مثل في نحو: ﴿صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ﴾⟪1:7⟫\nوحكي: مررت بالرجل مثلك، وذلك أنهما (الأولين) أي هما أولى من غيرهما، لأنهما أعرف بأحوال الميت، ولأنهما من المسلمين، فإن الخطاب من أول الآية مصروف إليهم،\n⟦5:485⟧\nوقوله: (عليهم) يحتمل ثلاثة أوجه: الأول: أن يكون (على) باقي على\nظاهره كقولهم: استحق على فلان مال، أي لزمه ووجب عليه الخروج\nمنه.\nالثاني: أن يكون قوله: (على) بمنزلة (من) كقوله: ﴿ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ﴾⟪83:2⟫ أي منهم.\nالثالث: أن يكون بمنزلة في موضع (على) مقام (في) كما وضع (في) مكان (على) في قوله: ﴿وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ﴾⟪20:71⟫.\nوقرأ إسحاق (عليهما الأوليان)\n⟦5:486⟧\nفيكون لهذا مرتفع، قوله: (الأولين) بقوله: (استحق) والمفعول\nالذي هو المستحق محذوف.\nوقرأ: ﴿مِنَ ٱلَّذِينَ ٱسۡتَحَقَّ عَلَيۡهِمُ ٱلۡأَوۡلَيَٰنِ﴾⟪5:107⟫ الجمع، أي من الأولين الذين استحق عليهم، هذا المعنى فيكون\nقوله: (الأولين) بدلا من الذين.\nوقرأ ابن سيرين: ﴿مِنَ ٱلَّذِينَ ٱسۡتَحَقَّ عَلَيۡهِمُ ٱلۡأَوۡلَيَٰنِ﴾⟪5:107⟫ تثنية الأول وليس ذلك بالوجه، فقد قال: ﴿فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا﴾⟪5:107⟫ فكيف يقول بعده الأولين."}, {"a": [108], "v": 5, "p": 486, "ev": 5, "ep": 487, "sid": 1978, "t": "قوله عز وجل: (ذلك أدنى أن يأتوا بالشهادة على وجهها أو يخافوا أن ترد أيمان بعد أيمانهم واتقوا الله واسمعوا والله لا يهدي القوم الفاسقين (108)\n⟦5:487⟧\nأن يتحرى هذا الفعل ومرجاته أقرب إلى الإنسان إما لصلاحه\nفي نفسه، وإما لخوفه أن ترد أيمانه على الأوليان بعد أيمانهم فيحلفوا على جنايتهم فيفضحوا، فيقيمون الشهادة على وجهها تفاديا من ذلك،\nثم قال: ﴿وَٱتَّقُواْ ٱللَّهَ وَٱسۡمَعُواْۗ﴾⟪5:108⟫ إما توحدون به فإنكم إن لم تتقوا ولم تسمعوا لصرتم فاسقين، فإذا فسقتم لم يهديكم الله، فالله لا يهدي القوم الفاسقين. إن قيل لم قال: (يأتوا) فذكر بلفظ الجمع، وما تقدم هو تثنية؟\nقيل: لأنه لم يعنهما فقط بل عنى الناس كلهم، أي ذلك أدنى أن يصير الناس هكذا."}, {"a": [109], "v": 5, "p": 487, "ev": 5, "ep": 489, "sid": 1979, "t": "قوله تعالى: (يوم يجمع الله الرسل فيقول ماذا أجبتم قالوا لا علم لنا إنك أنت علام الغيوب (109)\nقيل تقدير الآية: (والله لا يهدي القوم الفاسقين (108) يوم يجمع الله الرسل) الآية،\nوإنما المعنى لا يهديهم إلى طريق الجنة في ذلك اليوم.\nوقيل: معناه اذكروا يوم، ويكون اليوم مفعول فعل مضمر لا ظرفا،\nلأنه لم يرد اذكروا في ذلك اليوم.\n⟦5:488⟧\nإن قيل: كيف قالوا لا علم لنا، فنفوا العلم كله عن\nأنفسهم وذلك كذب؟\nقيل: في ذلك أوجه: الأول: قال الحسن: من هول\nذلك اليوم نسوا كل ما عملوه،\nفإن قيل: وكيف يصح ذلك، وقد قال: ﴿وَلَا خَوۡفٌ عَلَيۡهِمۡ﴾،\nوقال: ﴿لَا يَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ﴾⟪21:103⟫؟\nقيل: إن معنى لا يحزنهم ولا خوف عليهم أنه لا يصيبهم ما يقتضيه\nالخوف، إلا أنه يعتريهم، وهذا كقولك لمن يرتعد خوفا لا خوفا عليك، أي\nلا يحق خوفك.\nالثاني: قال ابن عباس: لا علم لنا بالإضافة إلى علمك، وهذا\nلمن استخبر من هو أعلم بالخبر منه، فيقول: لا علم لي.\nالتالث: أن السؤال يقع على ما اعتقده، لا ما أظهروه، وذلك لا علم للأنبياء به، إنما يعلمه المطلع.\n⟦5:489⟧\nعلى السرائر والضمائر جل وعز.\nالرابع: أن قوله: ﴿مَاذَآ أُجِبۡتُمۡۖ﴾⟪5:109⟫ سؤال عن كل ما أجيبوا، لا عن بعضه، وهم عرفوا بعض ذلك، ولم يعرفوا أكثره، فقالوا: لا علم بكل ذلك\nووجه هذا السؤال توبيخ الكفار كقوله: ﴿ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي﴾⟪5:116⟫، وعلام: لمن كثر علمه، ولم يوالي بعلمه، وهو في هذا الموضع لهما."}, {"a": [110], "v": 5, "p": 489, "ev": 5, "ep": 492, "sid": 1981, "t": "قوله عز وجل: (إذ قال الله يا عيسى ابن مريم اذكر نعمتي عليك وعلى والدتك إذ أيدتك بروح القدس تكلم الناس في المهد وكهلا وإذ علمتك الكتاب والحكمة والتوراة والإنجيل وإذ تخلق من الطين كهيئة الطير بإذني فتنفخ فيها فتكون طيرا بإذني وتبرئ الأكمه والأبرص بإذني وإذ تخرج الموتى بإذني وإذ كففت بني إسرائيل عنك إذ جئتهم بالبينات فقال الذين كفروا منهم إن هذا إلا سحر مبين (110)\n⟦5:490⟧\nقوله: ﴿إِذۡ قَالَ ٱللَّهُ﴾⟪5:110⟫ قيل: مفعول بفعل مضمر\nكأنه قيل: اذكر وقت ما قال الله يا عيسى اذكر نعمتي عليك، يعني: اذكر يوم القيامة، وقيل تقديره: ماذا أجبتم إذ قال الله.\n(وإذ أيدتك) فعلت من الأيد أي القوة، وقرأ (أيدتك) وهو أفعلت منه، وقال الزجاج: يجوز أن يكون فاعلت منه نحو عاونت.\nومن نعمة الله على والدتك أن اصطفاها على نساء العالمين، وأن جعل لها النخل حيث قال:\n⟦5:491⟧\n﴿وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ﴾⟪19:25⟫ وغير ذلك.\nوروح القدس: جبريل.\nقيل: هو تقديسه وروحه هو نفخة فيها من روحه.\nوالكتاب قيل: عنى بالكتاب، وقيل: بل باسم كل كتاب أنزله تعالى، ثم خص التوراة والإنجيل تعظيما لهما.\nوقوله: ﴿تُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗاۖ﴾⟪5:110⟫ أي تهدي الناس في حالة الصغر\nوالكبر بخلاف ما كان عامة الأنبياء والحكماء، وذكر الإذن في الأمور الإلهية التي خصه الله تعالى بها تنبيها أن ذلك لم يكن للآلهة فيه بل كان ذلك بإذنه ومن فضله عليه، وتخصيصه به، ولم يذكر في قوله: ﴿وَإِذۡ عَلَّمۡتُكَ﴾⟪5:110⟫ وفي قوله: ﴿وَإِذۡ كَفَفۡتُ﴾⟪5:110⟫ فإن في هذين قد شارك المسيح غيره.\nوكف بني إسرائيل عنه قد كان من بعضهم بالعصمة، ومن بعضهم بالحجة، ومن بعضهم\n⟦5:492⟧\nبتسخيرهم له وائقيادهم إلى غير ذلك من الوجوه،\nوقوله: ﴿إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ﴾⟪5:110⟫ أي فعلك سحر، وقرأ ﴿إِنۡ هَٰذَآ إِلَّا سِحۡرٞ﴾⟪5:110⟫ أي عيسى عليه الصلاة والسلام."}, {"a": [111], "v": 5, "p": 492, "ev": 5, "ep": 493, "sid": 1984, "t": "قوله عز وجل: (وإذ أوحيت إلى الحواريين أن آمنوا بي وبرسولي قالوا آمنا واشهد بأننا مسلمون (111)\nالحواريون، روي أنهم كانوا قصارين، وروي أنهم كانوا صيادين.\nوقد قال بعض المحققين: يعني أنهم سموا حواريين، أي كانوا يغسلون نفوس البشر عن النجاسات النفسية، ويعني أنهم صيادون أنهم يصيدون الناس عن\nالباطل، ويجعلونهم في شبكة الحق، وقد شرح ذلك في كتاب (مكارم\nالشريعة)، وسمي حاشية الرجل حوارية تشبيها بأصحاب عيسى عليه الصلاة\nوالسلام.\nوالوحي هنا قيل: هو على سبيل الإلهام، والتوفيق نحو:\n⟦5:493⟧\n﴿وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ﴾⟪16:68⟫ وقيل: هو على سبيل الابتلاء لهم من آياته\nالباهرة.\nوقيل: على لسان نبيهم، فالوحي قد يقال في كل ذلك نحو:\n﴿وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحۡيًا﴾⟪42:51⟫ أي على لسان نبي.\nوقوله: ﴿وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ﴾⟪16:68⟫ يعى بالإلهام.\nوقوله: ﴿فَأَوۡحَىٰٓ إِلَيۡهِمۡ أَن سَبِّحُواْ بُكۡرَةٗ وَعَشِيّٗا﴾⟪19:11⟫\nقال بعض الحكماء: كما أن كل ساكت ناطق من جهة الدلالة،\nفكل دال على معنى من الله فهو وحي منه وعلى هذا قال:\n(أفلم يسيروا في الأرض فتكون لهم قلوب يعقلون بها أو آذان يسمعون بها فإنها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور (46).\nوهذا معطوف على ما ذكر تعالى.\nومن نعمه عليه فهمه، وأشهد خطاب فهم لعيسى على سبيل الاستشهاد\nمنهم، والإسلام هاهنا أبلغ من الكتاب فإنه يقتضي الاستسلام المذكور في قوله: (إذ قال له ربه أسلم قال أسلمت لرب العالمين (131)."}];
